head.b:skin:
/*
  Theme Name: Singh Creative Studio Premium Light Portfolio
  Founder: MUKESH SINGH
  Tagline: Ideas Made Visible.
*/
:root {
  --bg: #FFFFFF;
  --panel: #F5F8FF;
  --card: #FFFFFF;
  --primary: #4F46E5;
  --electric: #2563EB;
  --cyan: #06B6D4;
  --violet: #8B5CF6;
  --text: #111827;
  --muted: #64748B;
  --border: #E5EAF3;
  --glow: rgba(79, 70, 229, 0.14);
  --shadow-sm: 0 4px 12px rgba(17, 24, 39, 0.04);
  --shadow-md: 0 12px 28px rgba(79, 70, 229, 0.08);
  --shadow-lg: 0 20px 48px rgba(79, 70, 229, 0.12);
  --max: 1280px;
  --font-heading: 'Space Grotesk', sans-serif;
  --font-body: 'DM Sans', sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
  font-size: 16px;
  -webkit-tap-highlight-color: transparent;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  line-height: 1.6;
  overflow-x: hidden;
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

button, input, select, textarea {
  font-family: inherit;
  font-size: inherit;
  background: none;
  border: none;
  color: inherit;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

svg {
  max-width: 100%;
}

.container {
  width: min(var(--max), calc(100% - 48px));
  margin-left: auto;
  margin-right: auto;
}

.display {
  font-family: var(--font-heading);
  letter-spacing: -0.05em;
}

.gradient-text {
  background: linear-gradient(135deg, #4F46E5 0%, #2563EB 50%, #06B6D4 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.eyebrow {
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.eyebrow::before {
  content: '';
  width: 24px;
  height: 2px;
  background: var(--primary);
  border-radius: 2px;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 18px;
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--primary);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  background: #FFFFFF;
  box-shadow: var(--shadow-sm);
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  flex-shrink: 0;
}

/* Buttons & Interactive Elements */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 28px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: -0.01em;
  transition: all 0.28s cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
  white-space: nowrap;
  border: 1px solid transparent;
}

.btn:hover {
  transform: translateY(-3px);
}

.btn-primary {
  background: linear-gradient(135deg, #4F46E5, #2563EB, #06B6D4);
  color: #FFFFFF;
  box-shadow: 0 8px 24px rgba(79, 70, 229, 0.25);
}

.btn-primary:hover {
  box-shadow: 0 12px 32px rgba(79, 70, 229, 0.4);
  color: #FFFFFF;
}

.btn-ghost {
  border-color: var(--primary);
  background: #FFFFFF;
  color: var(--primary);
  box-shadow: var(--shadow-sm);
}

.btn-ghost:hover {
  background: rgba(79, 70, 229, 0.06);
  border-color: var(--electric);
  color: var(--electric);
}

/* Circular Icon Buttons */
.btn-icon {
  width: 46px;
  height: 46px;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: #FFFFFF;
  color: var(--text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: all 0.25s ease;
  flex-shrink: 0;
}

.btn-icon svg {
  width: 20px;
  height: 20px;
  display: block;
}

.btn-icon svg line,
.btn-icon svg path,
.btn-icon svg circle,
.btn-icon svg rect,
.btn-icon svg polygon,
.btn-icon svg polyline {
  fill: none;
  stroke: #111827 !important;
  stroke-width: 2.2px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.btn-icon.active svg line,
.btn-icon.active svg path,
.btn-icon.active svg circle,
.btn-icon.active svg rect,
.btn-icon.active svg polygon,
.btn-icon.active svg polyline {
  stroke: #FFFFFF !important;
}

.btn-icon:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(79, 70, 229, 0.05);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-icon.active {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  color: #FFFFFF;
  border-color: transparent;
}

/* Topline Accent Bar */
.topline {
  height: 3px;
  background: linear-gradient(90deg, var(--primary), var(--cyan), var(--violet));
  position: relative;
  z-index: 1000;
}

/* Light Intro Screen with Cinematic Transition */
.intro {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  padding: 24px;
  background: radial-gradient(ellipse at 50% 35%, rgba(79, 70, 229, 0.12), transparent 60%), #FFFFFF;
  transition: opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1), transform 0.8s cubic-bezier(0.22, 1, 0.36, 1), visibility 0.8s;
  overflow: hidden;
}

.intro-glow-bg {
  position: absolute;
  inset: -50%;
  background: radial-gradient(circle at 50% 50%, rgba(79, 70, 229, 0.35), rgba(37, 99, 235, 0.2), rgba(6, 182, 212, 0.15), transparent 70%);
  opacity: 0;
  transform: scale(0.3);
  transition: transform 1.1s cubic-bezier(0.22, 1, 0.36, 1), opacity 1.1s cubic-bezier(0.22, 1, 0.36, 1);
  pointer-events: none;
  z-index: 1;
}

.intro.transitioning .intro-glow-bg {
  opacity: 1;
  transform: scale(1.8);
}

.intro.hidden {
  opacity: 0;
  transform: scale(1.04);
  visibility: hidden;
  pointer-events: none;
}

.intro-inner {
  text-align: center;
  max-width: 680px;
  position: relative;
  z-index: 2;
  transition: transform 0.8s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.intro.transitioning .intro-inner {
  transform: scale(1.06) translateY(-12px);
  opacity: 0;
}

#enterStudio {
  position: relative;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.3s cubic-bezier(0.22, 1, 0.36, 1), background 0.3s ease;
}

#enterStudio.active-cta {
  transform: scale(0.95);
  box-shadow: 0 0 35px rgba(79, 70, 229, 0.6), 0 0 60px rgba(6, 182, 212, 0.4);
}

body.intro-dismissed .header,
body.intro-dismissed .hero-copy,
body.intro-dismissed .visual-wrap {
  animation: heroEntrance 1.1s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@keyframes heroEntrance {
  0% {
    opacity: 0;
    transform: translateY(20px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.logo-monogram {
  width: 80px;
  height: 80px;
  border-radius: 24px;
  margin: 0 auto 24px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--primary) 0%, var(--electric) 50%, var(--cyan) 100%);
  color: #FFFFFF;
  font: 800 2.6rem var(--font-heading);
  box-shadow: 0 12px 36px rgba(79, 70, 229, 0.3);
  transform: rotate(-6deg);
  transition: transform 0.4s ease;
}

.logo-monogram:hover {
  transform: rotate(0deg) scale(1.05);
}

.logo-monogram span {
  transform: rotate(6deg);
  display: block;
}

.intro h1 {
  font: 800 clamp(2.4rem, 7.5vw, 4.8rem) / 1.02 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 0;
  color: var(--text);
}

.intro .founder {
  font-size: 0.8rem;
  font-weight: 800;
  letter-spacing: 0.35em;
  color: var(--primary);
  margin: 18px 0 6px;
  text-transform: uppercase;
}

.intro .tagline {
  color: var(--muted);
  font-size: 1.1rem;
  margin: 0 0 32px;
}

.intro-orbit {
  position: absolute;
  width: min(85vw, 650px);
  height: min(85vw, 650px);
  border: 1px solid rgba(79, 70, 229, 0.12);
  border-radius: 50%;
  pointer-events: none;
  z-index: 1;
}

.intro-orbit::after {
  content: '';
  position: absolute;
  inset: 12%;
  border: 1px dashed rgba(6, 182, 212, 0.25);
  border-radius: 50%;
  animation: spin 35s linear infinite;
}

/* Main Header & Navigation */
.header {
  position: sticky;
  top: 0;
  z-index: 900;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border);
}

.nav {
  height: 80px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font: 700 1.15rem var(--font-heading);
  letter-spacing: -0.03em;
  color: var(--text);
  transition: opacity 0.2s;
}

.brand:hover {
  opacity: 0.85;
}

.brand-icon {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--primary), var(--cyan));
  color: #FFFFFF;
  font: 800 1.3rem var(--font-heading);
  box-shadow: 0 4px 16px rgba(79, 70, 229, 0.2);
}

.navlinks {
  display: flex;
  align-items: center;
  gap: 32px;
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 600;
}

.navlinks a {
  transition: color 0.2s ease;
}

.navlinks a:hover {
  color: var(--primary);
}

.navlinks .navcta {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  color: #FFFFFF;
  padding: 10px 22px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 0.88rem;
  box-shadow: 0 4px 14px rgba(79, 70, 229, 0.2);
  transition: transform 0.2s, box-shadow 0.2s;
}

.navlinks .navcta:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(79, 70, 229, 0.35);
  color: #FFFFFF;
}

.menu-toggle {
  display: none;
}

.menu-toggle svg {
  display: block;
  width: 22px;
  height: 22px;
  stroke: var(--text-main);
  stroke-width: 2.5;
  stroke-linecap: round;
}

/* Light Hero Section */
.hero {
  position: relative;
  padding: 90px 0 75px;
  overflow: hidden;
  background: radial-gradient(circle at 80% 20%, rgba(79, 70, 229, 0.06) 0%, transparent 60%), #FFFFFF;
}

.hero::before {
  content: '';
  position: absolute;
  width: 550px;
  height: 550px;
  right: -200px;
  top: -150px;
  background: rgba(79, 70, 229, 0.08);
  filter: blur(120px);
  border-radius: 50%;
  pointer-events: none;
}

.hero-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr 1.05fr;
  gap: 48px;
  align-items: center;
}

.hero-copy h2 {
  font: 800 clamp(3.2rem, 5.8vw, 5.8rem) / 0.98 var(--font-heading);
  letter-spacing: -0.065em;
  margin: 22px 0;
  color: var(--text);
}

.hero-copy p {
  color: var(--muted);
  max-width: 520px;
  font-size: 1.08rem;
  line-height: 1.65;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 32px;
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 36px;
  color: var(--muted);
  font-size: 0.85rem;
}

.hero-meta b {
  color: var(--primary);
  font-weight: 700;
}

/* Visual Artwork Showcase & Carousel */
.visual-wrap {
  position: relative;
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 28px;
  background: #FFFFFF;
  box-shadow: var(--shadow-lg);
}

.visual-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  padding: 4px 6px 14px;
}

.window-dots {
  display: flex;
  gap: 6px;
}

.window-dots i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #CBD5E1;
  display: block;
}

.window-dots i:first-child { background: var(--primary); }
.window-dots i:nth-child(2) { background: var(--electric); }
.window-dots i:nth-child(3) { background: var(--cyan); }

.visual-canvas {
  position: relative;
  overflow: hidden;
  aspect-ratio: 1.1 / 1;
  border-radius: 18px;
  background: #F8FAFC;
  border: 1px solid var(--border);
  isolation: isolate;
}

.scene {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  opacity: 0;
  transform: scale(0.95);
  transition: opacity 0.6s ease, transform 0.6s ease;
  pointer-events: none;
}

.scene.active {
  opacity: 1;
  transform: scale(1);
  pointer-events: auto;
}

.scene svg {
  width: 100%;
  height: 100%;
  display: block;
}

.float-tag {
  position: absolute;
  z-index: 10;
  padding: 10px 16px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: var(--shadow-md);
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text);
  backdrop-filter: blur(12px);
  animation: float 5s ease-in-out infinite;
  display: flex;
  align-items: center;
  gap: 8px;
}

.tag-one { left: -16px; top: 22%; }
.tag-two { right: -16px; bottom: 22%; animation-delay: -2.5s; }

.tag-icon {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  background: linear-gradient(135deg, var(--primary), var(--electric));
  color: #FFFFFF;
  border-radius: 6px;
  font-weight: 900;
  font-size: 0.8rem;
}

.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 6px 4px;
}

.carousel-info strong {
  font: 700 1.05rem var(--font-heading);
  display: block;
  color: var(--text);
}

.carousel-info span {
  font-size: 0.78rem;
  color: var(--muted);
}

.carousel-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}

.carousel-progress {
  height: 3px;
  background: var(--border);
  border-radius: 3px;
  margin-top: 10px;
  overflow: hidden;
}

.carousel-progress-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--primary), var(--cyan));
  transition: width 0.3s linear;
}

/* Ticker Banner */
.ticker {
  overflow: hidden;
  border-block: 1px solid var(--border);
  background: var(--panel);
  user-select: none;
}

.ticker-track {
  display: flex;
  align-items: center;
  gap: 32px;
  width: max-content;
  padding: 18px 0;
  animation: ticker 28s linear infinite;
}

.ticker-track span {
  font: 700 0.88rem var(--font-heading);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text);
  white-space: nowrap;
}

.ticker-track b {
  color: var(--primary);
  font-size: 1.1rem;
}

/* Section Utility */
.section {
  padding: 100px 0;
}

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: 48px;
}

.section-head h2 {
  font: 800 clamp(2.4rem, 5vw, 4.2rem) / 1.02 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 14px 0 0;
  color: var(--text);
}

.section-head p {
  max-width: 440px;
  color: var(--muted);
  margin: 0;
  font-size: 1.02rem;
}

/* Services Grid */
.services {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.service {
  position: relative;
  overflow: hidden;
  min-height: 260px;
  padding: 28px;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: var(--card);
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.3s, box-shadow 0.3s;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.service::after {
  content: '';
  position: absolute;
  width: 120px;
  height: 120px;
  right: -60px;
  bottom: -60px;
  border-radius: 50%;
  background: var(--primary);
  filter: blur(45px);
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
}

.service:hover {
  transform: translateY(-8px);
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
}

.service:hover::after {
  opacity: 0.15;
}

.service-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.service-icon {
  width: 50px;
  height: 50px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(79, 70, 229, 0.1), rgba(6, 182, 212, 0.1));
  color: var(--primary);
  font-size: 1.4rem;
  font-weight: 700;
}

.service .number {
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.service h3 {
  font: 700 1.25rem var(--font-heading);
  margin: 24px 0 10px;
  color: var(--text);
}

.service p {
  font-size: 0.88rem;
  color: var(--muted);
  line-height: 1.6;
  margin: 0;
}

/* Portfolio Section */
.work-section {
  background: var(--panel);
  border-block: 1px solid var(--border);
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 32px;
}

.filter {
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 10px 22px;
  background: #FFFFFF;
  color: var(--text);
  cursor: pointer;
  font-size: 0.85rem;
  font-weight: 700;
  box-shadow: var(--shadow-sm);
  transition: all 0.25s ease;
}

.filter.active, .filter:hover {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  border-color: transparent;
  color: #FFFFFF;
  box-shadow: 0 6px 20px rgba(79, 70, 229, 0.3);
}

.projects {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.project {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 20px;
  background: #FFFFFF;
  box-shadow: var(--shadow-sm);
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.35s, box-shadow 0.35s;
  display: flex;
  flex-direction: column;
}

.project:hover {
  transform: translateY(-7px);
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
}

.project[hidden] {
  display: none !important;
}

.project-art {
  position: relative;
  overflow: hidden;
  aspect-ratio: 1.45 / 1;
  background: #F8FAFC;
  width: 100%;
  height: 100%;
}

.project-art svg {
  width: 100%;
  height: 100%;
  display: block;
  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.project:hover .project-art svg {
  transform: scale(1.05);
}

.concept-badge {
  position: absolute;
  bottom: 14px;
  left: 14px;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.15em;
  color: var(--primary);
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 10px;
  backdrop-filter: blur(8px);
  box-shadow: var(--shadow-sm);
}

.project-info {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 20px 22px;
  background: #FFFFFF;
  margin-top: auto;
}

.project-info h3 {
  font: 700 1.15rem var(--font-heading);
  margin: 0;
  color: var(--text);
}

.project-info p {
  color: var(--muted);
  font-size: 0.8rem;
  margin: 4px 0 0;
}

.project-link {
  width: 38px;
  height: 38px;
  border: 1px solid var(--border);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--primary);
  flex-shrink: 0;
  transition: all 0.2s;
}

.project:hover .project-link {
  background: var(--primary);
  color: #FFFFFF;
  border-color: var(--primary);
}

/* Motion Lab Section */
.feature {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  padding: 56px;
  border: 1px solid var(--border);
  border-radius: 28px;
  background: radial-gradient(ellipse at 90% 30%, rgba(79, 70, 229, 0.08), transparent 50%), #F5F8FF;
  overflow: hidden;
  position: relative;
  box-shadow: var(--shadow-sm);
}

.feature h2 {
  font: 800 clamp(2.5rem, 5vw, 4.4rem) / 1 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 16px 0 20px;
  color: var(--text);
}

.feature p {
  color: var(--muted);
  max-width: 480px;
  font-size: 1.05rem;
  margin-bottom: 32px;
}

.feature-art {
  position: relative;
  min-height: 320px;
  display: grid;
  place-items: center;
}

.orb {
  width: 190px;
  height: 190px;
  border-radius: 40%;
  background: linear-gradient(140deg, #4F46E5 0%, #2563EB 35%, #06B6D4 70%, #8B5CF6 100%);
  box-shadow: inset -15px -15px 35px rgba(255, 255, 255, 0.4), 0 12px 40px rgba(79, 70, 229, 0.25);
  transform: rotate(25deg);
  animation: float 6s ease-in-out infinite;
}

.orb-ring {
  position: absolute;
  width: 300px;
  height: 120px;
  border: 2px solid rgba(79, 70, 229, 0.4);
  border-radius: 50%;
  transform: rotate(-28deg);
  animation: spin 24s linear infinite;
}

.orb-ring.two {
  width: 320px;
  height: 140px;
  transform: rotate(55deg);
  border-color: rgba(6, 182, 212, 0.4);
  animation-direction: reverse;
}

/* About Mukesh Singh */
.about-grid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 56px;
  align-items: center;
}

.about-art {
  min-height: 400px;
  position: relative;
  display: grid;
  place-items: center;
  border: 1px solid var(--border);
  border-radius: 24px;
  background: radial-gradient(circle at 50% 40%, rgba(79, 70, 229, 0.1), transparent 60%), #F5F8FF;
  overflow: hidden;
}

.about-art::before {
  content: 'MUKESH SINGH / CREATIVE DIRECTOR';
  position: absolute;
  bottom: 22px;
  left: 22px;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--muted);
}

.monogram {
  font: 900 clamp(7rem, 16vw, 13rem) / 1 var(--font-heading);
  letter-spacing: -0.12em;
  color: transparent;
  -webkit-text-stroke: 2px var(--primary);
  text-shadow: 10px 10px 0 rgba(79, 70, 229, 0.12);
  transform: rotate(-6deg);
  user-select: none;
}

.about-copy h2 {
  font: 800 clamp(2.5rem, 5vw, 4.2rem) / 1.02 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 16px 0;
  color: var(--text);
}

.about-copy p {
  color: var(--muted);
  font-size: 1.05rem;
  margin-bottom: 16px;
}

.skills {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 28px 0 32px;
}

.skills span {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 8px 16px;
  color: var(--text);
  font-size: 0.82rem;
  font-weight: 700;
  background: #FFFFFF;
  box-shadow: var(--shadow-sm);
}

/* Contact Section & Footer */
.contact {
  padding: 110px 0;
  text-align: center;
  background: radial-gradient(ellipse at 50% 100%, rgba(79, 70, 229, 0.08), transparent 65%), #FFFFFF;
}

.contact h2 {
  font: 800 clamp(2.8rem, 7vw, 5.8rem) / 0.98 var(--font-heading);
  letter-spacing: -0.06em;
  margin: 20px 0;
  color: var(--text);
}

.contact p {
  max-width: 580px;
  margin: 0 auto 32px;
  color: var(--muted);
  font-size: 1.08rem;
}

.contact-actions {
  display: flex;
  justify-content: center;
  gap: 14px;
  flex-wrap: wrap;
}

/* WhatsApp Quotation Form Styles */
.quote-card {
  max-width: 680px;
  margin: 48px auto 40px;
  background: #FFFFFF;
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 44px 36px;
  box-shadow: 0 20px 48px rgba(79, 70, 229, 0.08), 0 4px 12px rgba(17, 24, 39, 0.03);
  text-align: left;
  position: relative;
  overflow: hidden;
}

.quote-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, #4F46E5, #2563EB, #06B6D4);
}

.quote-card-head {
  margin-bottom: 28px;
  text-align: center;
}

.quote-card-title {
  font-family: var(--font-heading);
  font-size: clamp(1.5rem, 3.2vw, 2rem);
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}

.quote-card-sub {
  font-size: 0.95rem;
  color: var(--muted);
  line-height: 1.5;
  margin: 0;
}

.quote-form {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.form-label {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text);
  letter-spacing: -0.01em;
}

.form-label .req {
  color: #EF4444;
  margin-left: 2px;
}

.form-control {
  width: 100%;
  background: #F8FAFC;
  border: 1.5px solid var(--border);
  border-radius: 12px;
  padding: 14px 16px;
  font-size: 0.95rem;
  font-family: var(--font-body);
  color: var(--text);
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
  box-sizing: border-box;
  outline: none;
}

.form-control::placeholder {
  color: #94A3B8;
}

.form-control:focus {
  background: #FFFFFF;
  border-color: #4F46E5;
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.form-control.field-error {
  border-color: #EF4444;
  background: #FFFBFB;
}

.form-control.field-error:focus {
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.15);
}

select.form-control {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%2364748B' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: right 14px center;
  background-size: 16px;
  padding-right: 40px;
  cursor: pointer;
}

textarea.form-control {
  resize: vertical;
  min-height: 120px;
  line-height: 1.55;
}

.field-error-msg {
  font-size: 0.82rem;
  color: #EF4444;
  display: none;
  margin-top: 2px;
  font-weight: 500;
}

.field-error-msg.visible {
  display: block;
}

.btn-whatsapp-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  padding: 16px 28px;
  background: linear-gradient(135deg, #25D366 0%, #128C7E 100%);
  color: #FFFFFF;
  font-family: var(--font-heading);
  font-size: 1.02rem;
  font-weight: 600;
  border-radius: 12px;
  border: none;
  cursor: pointer;
  box-shadow: 0 10px 24px rgba(37, 211, 102, 0.28);
  transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
  margin-top: 6px;
}

.btn-whatsapp-submit:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 30px rgba(37, 211, 102, 0.35);
  filter: brightness(1.03);
}

.btn-whatsapp-submit:active {
  transform: translateY(0);
  box-shadow: 0 6px 16px rgba(37, 211, 102, 0.24);
}

.btn-whatsapp-submit:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(37, 211, 102, 0.4);
}

.btn-whatsapp-submit svg {
  width: 22px;
  height: 22px;
  fill: #FFFFFF;
  flex-shrink: 0;
}

.quote-status-feedback {
  font-size: 0.9rem;
  padding: 12px 16px;
  border-radius: 10px;
  text-align: center;
  margin-top: 8px;
  display: none;
  line-height: 1.45;
}

.quote-status-feedback.info {
  display: block;
  background: #EFF6FF;
  border: 1px solid #BFDBFE;
  color: #1D4ED8;
}

.quote-status-feedback.error {
  display: block;
  background: #FEF2F2;
  border: 1px solid #FECACA;
  color: #B91C1C;
}

@media (max-width: 640px) {
  .quote-card {
    padding: 32px 20px;
    margin: 36px auto 32px;
    border-radius: 20px;
  }
  .btn-whatsapp-submit {
    padding: 14px 20px;
    font-size: 0.96rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .btn-whatsapp-submit,
  .form-control {
    transition: none !important;
  }
  .btn-whatsapp-submit:hover {
    transform: none !important;
  }
}


/* Premium Responsive Footer Styles */
.footer {
  border-top: 1px solid var(--border);
  padding: 60px 0 32px;
  color: var(--muted);
  font-size: 0.9rem;
  background: #F8FAFC;
  position: relative;
  overflow: hidden;
}

.footer-content {
  display: grid;
  grid-template-columns: 2fr 1fr 2fr;
  gap: 48px;
  margin-bottom: 40px;
}

.footer-brand {
  margin-bottom: 16px;
  display: inline-flex;
  align-items: center;
  gap: 12px;
}

.footer-brand-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--text);
}

.footer-founder {
  font-size: 0.95rem;
  color: var(--text);
  margin-bottom: 4px;
}

.footer-tagline {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  background: linear-gradient(135deg, var(--primary) 0%, var(--electric) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 12px;
}

.footer-desc {
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--muted);
  max-width: 420px;
}

.footer-heading {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 16px;
  letter-spacing: -0.01em;
}

.footer-nav-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-nav-list a {
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s ease, transform 0.2s ease;
  display: inline-block;
}

.footer-nav-list a:hover,
.footer-nav-list a:focus-visible {
  color: var(--primary);
  transform: translateX(4px);
}

.footer-subtext {
  font-size: 0.88rem;
  line-height: 1.5;
  margin-bottom: 16px;
  color: var(--muted);
}

.footer-social-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.footer-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  min-height: 44px;
  border-radius: 12px;
  background: #FFFFFF;
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 0.88rem;
  font-weight: 600;
  text-decoration: none;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease, color 0.2s ease;
}

.footer-action-btn:hover,
.footer-action-btn:focus-visible {
  border-color: var(--primary);
  color: var(--primary);
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(79, 70, 229, 0.12);
}

.footer-action-btn.footer-quote-btn {
  background: linear-gradient(135deg, rgba(79, 70, 229, 0.08) 0%, rgba(6, 182, 212, 0.08) 100%);
  border-color: rgba(79, 70, 229, 0.3);
  color: var(--primary);
}

.footer-action-btn.footer-quote-btn:hover,
.footer-action-btn.footer-quote-btn:focus-visible {
  background: linear-gradient(135deg, var(--primary) 0%, var(--electric) 100%);
  color: #FFFFFF;
  border-color: transparent;
  box-shadow: 0 8px 20px rgba(79, 70, 229, 0.25);
}

.footer-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
}

.footer-bottom-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.85rem;
  color: var(--muted);
  flex-wrap: wrap;
  gap: 12px;
}

.footer-credit strong {
  color: var(--text);
}

/* Reveal animation */
.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.7s cubic-bezier(0.16, 1, 0.3, 1), transform 0.7s cubic-bezier(0.16, 1, 0.3, 1);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

.blogger-hidden {
  display: none !important;
}

/* Animations */
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-14px); }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@keyframes ticker {
  to { transform: translateX(-50%); }
}

/* Responsive Design */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .hero-copy {
    text-align: center;
  }
  .hero-copy p {
    margin-inline: auto;
  }
  .hero-actions, .hero-meta {
    justify-content: center;
  }
  .visual-wrap {
    width: min(100%, 680px);
    margin: auto;
  }
  .services {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .projects {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .about-grid {
    gap: 36px;
  }
  .feature {
    gap: 24px;
    padding: 40px;
  }
}

@media (max-width: 768px) {
  .container {
    width: calc(100% - 32px);
  }
  .nav {
    height: 70px;
  }
  .menu-toggle {
    display: inline-flex !important;
  }
  .navlinks {
    display: none;
    position: absolute;
    left: 0;
    right: 0;
    top: 70px;
    padding: 24px;
    background: #FFFFFF;
    border-bottom: 1px solid var(--border);
    flex-direction: column;
    align-items: stretch;
    gap: 18px;
    box-shadow: var(--shadow-lg);
  }
  .navlinks.open {
    display: flex;
  }
  .navlinks .navcta {
    text-align: center;
  }
  .hero {
    padding: 56px 0 48px;
  }
  .hero-copy h2 {
    font-size: clamp(2.8rem, 11vw, 4.4rem);
  }
  .visual-wrap {
    padding: 12px;
    border-radius: 20px;
  }
  .float-tag {
    font-size: 0.68rem;
    padding: 8px 12px;
  }
  .tag-one { left: -6px; }
  .tag-two { right: -6px; }
  .section {
    padding: 70px 0;
  }
  .section-head {
    display: block;
    margin-bottom: 32px;
  }
  .section-head p {
    margin-top: 14px;
  }
  .services {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .service {
    padding: 20px;
    min-height: auto;
  }
  .projects {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .feature {
    grid-template-columns: 1fr;
    padding: 32px 24px;
    gap: 12px;
  }
  .feature-art {
    min-height: 240px;
    grid-row: 1;
  }
  .orb { width: 140px; height: 140px; }
  .orb-ring { width: 230px; height: 95px; }
  .orb-ring.two { width: 250px; height: 110px; }
  .about-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }
  .about-art { min-height: 280px; }
  .monogram { font-size: 8.5rem; }
  .contact { padding: 75px 0; }
  .footer-content {
    grid-template-columns: 1fr;
    gap: 36px;
  }
  .footer-social-grid {
    grid-template-columns: 1fr;
  }
  .footer-bottom-inner {
    flex-direction: column;
    text-align: center;
    gap: 8px;
  }
}

@media (max-width: 480px) {
  .footer {
    padding: 44px 0 24px;
  }
  .footer-content {
    gap: 28px;
  }
  .footer-action-btn {
    width: 100%;
    justify-content: flex-start;
  }
}

@media (max-width: 390px) {
  .container {
    width: calc(100% - 24px);
  }
  .brand { font-size: 0.98rem; }
  .brand-icon { width: 34px; height: 34px; font-size: 1.1rem; }
  .hero-copy h2 { font-size: 2.6rem; }
  .hero-actions .btn { width: 100%; }
  .carousel-nav { flex-direction: column; align-items: flex-start; gap: 8px; }
  .intro h1 { font-size: 2.2rem; }
  .intro .btn { width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
  .reveal {
    opacity: 1;
    transform: none;
  }
}

/* ==========================================================================
   REELS & VERTICAL VIDEO SHOWCASE SECTION
   ========================================================================== */
.reels-section {
  background: radial-gradient(ellipse at 50% 0%, rgba(79, 70, 229, 0.05), transparent 70%), #FFFFFF;
  position: relative;
  overflow: hidden;
}

.reels-category-filters {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-bottom: 36px;
}

.reel-filter-btn {
  padding: 10px 22px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: #FFFFFF;
  color: var(--text);
  font-size: 0.85rem;
  font-weight: 700;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: all 0.25s ease;
}

.reel-filter-btn:hover,
.reel-filter-btn.active {
  background: linear-gradient(135deg, #4F46E5, #2563EB);
  color: #FFFFFF;
  border-color: transparent;
  box-shadow: 0 6px 20px rgba(79, 70, 229, 0.3);
}

.reels-carousel-container {
  position: relative;
  width: 100%;
  max-width: 1140px;
  margin: 0 auto;
  padding: 10px 0;
}

.reels-carousel-track-wrapper {
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: x mandatory;
  scroll-padding-inline: calc(50% - 140px);
  -webkit-overflow-scrolling: touch;
  touch-action: pan-y;
  padding: 20px 0;
  scrollbar-width: none;
}
.reels-carousel-track-wrapper::-webkit-scrollbar {
  display: none;
}

.reels-carousel-track {
  display: flex;
  align-items: center;
  gap: 28px;
  width: max-content;
  margin: 0 auto;
  touch-action: pan-y;
}

/* Vertical Reel Card Frame (9:16 aspect ratio) */
.reel-card {
  flex: 0 0 280px;
  width: 280px;
  scroll-snap-align: center;
  scroll-snap-stop: always;
  touch-action: pan-y;
  position: relative;
  border-radius: 24px;
  background: #000000;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.35s ease, box-shadow 0.35s ease;
  opacity: 0.65;
  transform: scale(0.92);
  user-select: none;
}

.reel-card.active {
  opacity: 1;
  transform: scale(1);
  box-shadow: 0 20px 48px rgba(79, 70, 229, 0.22);
  border-color: rgba(79, 70, 229, 0.4);
  z-index: 5;
}

.reel-frame-inner {
  position: relative;
  width: 100%;
  aspect-ratio: 9 / 16;
  background: #111827;
  overflow: hidden;
  border-radius: 23px;
}

.reel-thumbnail-wrap {
  position: absolute;
  inset: 0;
  z-index: 2;
  background-size: cover;
  background-position: center;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 16px;
  transition: opacity 0.35s ease;
}

.reel-thumbnail-wrap::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0.4) 0%, rgba(0,0,0,0) 40%, rgba(0,0,0,0.85) 100%);
  z-index: 1;
  pointer-events: none;
}

.reel-badge-category {
  position: relative;
  z-index: 2;
  align-self: flex-start;
  padding: 6px 14px;
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(8px);
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.reel-play-btn-wrap {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 3;
  cursor: pointer;
  border-radius: 50%;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.reel-play-btn {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: linear-gradient(135deg, #4F46E5, #2563EB, #06B6D4);
  color: #FFFFFF;
  display: grid;
  place-items: center;
  box-shadow: 0 10px 30px rgba(79, 70, 229, 0.4);
  transition: transform 0.25s ease;
}

.reel-play-btn svg {
  width: 26px;
  height: 26px;
  fill: #FFFFFF;
  margin-left: 3px;
}

.reel-card:hover .reel-play-btn-wrap {
  transform: translate(-50%, -50%) scale(1.1);
}

.reel-meta-bottom {
  position: relative;
  z-index: 2;
  color: #FFFFFF;
}

.reel-cover-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 0;
  pointer-events: none;
  border-radius: inherit;
  transition: transform 0.4s ease;
}

.reel-card:hover .reel-cover-img {
  transform: scale(1.04);
}

.reel-meta-title {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 6px;
  text-shadow: 0 2px 4px rgba(0,0,0,0.6);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  word-break: break-word;
}

.reel-meta-desc {
  font-size: 0.78rem;
  color: rgba(255, 255, 255, 0.85);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* YouTube IFrame Container inside Reel Card */
.reel-iframe-container {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
}

.reel-iframe-container iframe {
  width: 100%;
  height: 100%;
  border: none;
  display: block;
}

/* Error & Loading States inside Reel Card */
.reel-status-overlay {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: #0F172A;
  color: #FFFFFF;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  text-align: center;
  gap: 12px;
}

.reel-status-overlay.hidden {
  display: none;
}

.reel-spinner {
  width: 36px;
  height: 36px;
  border: 3px solid rgba(255,255,255,0.2);
  border-top-color: var(--cyan);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

.reel-error-text {
  font-size: 0.82rem;
  color: #F87171;
}

.reel-retry-btn {
  padding: 6px 14px;
  border-radius: 999px;
  background: rgba(255,255,255,0.15);
  color: #FFFFFF;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid rgba(255,255,255,0.2);
  transition: background 0.2s ease;
}

.reel-retry-btn:hover {
  background: rgba(255,255,255,0.3);
}

/* Carousel Navigation Footer */
.reels-carousel-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 580px;
  margin: 28px auto 0;
  padding: 0 16px;
}

.reels-counter {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.1rem;
  color: var(--text);
  letter-spacing: 0.05em;
}

.reels-counter span {
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 600;
}

/* Sound / Fullscreen / Carousel Control Row */
.reels-control-group {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* ==========================================================================
   GRAPHIC DESIGN GALLERY SECTION
   ========================================================================== */
.graphics-section {
  background: var(--panel);
  border-block: 1px solid var(--border);
}

.graphics-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
  margin-top: 32px;
}

.graphic-card {
  position: relative;
  border-radius: 18px;
  background: #FFFFFF;
  border: 1px solid var(--border);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.35s ease, border-color 0.35s ease;
  display: flex;
  flex-direction: column;
}

.graphic-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
  border-color: var(--primary);
}

.graphic-card[hidden] {
  display: none !important;
}

.graphic-image-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  background: #F1F5F9;
  overflow: hidden;
}

.graphic-image-wrap img,
.graphic-image-wrap svg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.graphic-card:hover .graphic-image-wrap img,
.graphic-card:hover .graphic-image-wrap svg {
  transform: scale(1.06);
}

.graphic-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--primary);
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 4px 8px;
  backdrop-filter: blur(8px);
  z-index: 2;
}

.graphic-info {
  padding: 16px 18px;
  background: #FFFFFF;
}

.graphic-info h3 {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: var(--text);
  margin: 0 0 4px;
}

.graphic-info p {
  font-size: 0.78rem;
  color: var(--muted);
  margin: 0;
}

/* ==========================================================================
   LIGHTBOX / MODAL FOR GRAPHIC PREVIEW
   ========================================================================== */
.lightbox-modal {
  position: fixed;
  inset: 0;
  z-index: 10000;
  background: rgba(17, 24, 39, 0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}

.lightbox-modal.open {
  opacity: 1;
  visibility: visible;
}

.lightbox-content-wrap {
  position: relative;
  max-width: 900px;
  width: 100%;
  background: #FFFFFF;
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 25px 60px rgba(0,0,0,0.3);
  display: flex;
  flex-direction: column;
  max-height: 90vh;
  transform: scale(0.92);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.lightbox-modal.open .lightbox-content-wrap {
  transform: scale(1);
}

.lightbox-body {
  position: relative;
  flex: 1;
  display: grid;
  place-items: center;
  background: #000000;
  overflow: hidden;
  max-height: 70vh;
}

.lightbox-body img,
.lightbox-body svg {
  max-width: 100%;
  max-height: 70vh;
  object-fit: contain;
  display: block;
}

.lightbox-meta-bar {
  padding: 20px 24px;
  background: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-top: 1px solid var(--border);
}

.lightbox-meta-title {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text);
}

.lightbox-meta-cat {
  font-size: 0.82rem;
  color: var(--muted);
  margin-top: 2px;
}

.lightbox-close-btn {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 10;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid var(--border);
  color: var(--text);
  display: grid;
  place-items: center;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: transform 0.2s ease, background 0.2s ease;
}

.lightbox-close-btn:hover {
  transform: scale(1.08);
  background: #FFFFFF;
}

.lightbox-nav-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid var(--border);
  color: var(--text);
  display: grid;
  place-items: center;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: transform 0.2s ease, background 0.2s ease;
}

.lightbox-nav-btn:hover {
  transform: translateY(-50%) scale(1.08);
  background: #FFFFFF;
}

.lightbox-nav-prev { left: 16px; }
.lightbox-nav-next { right: 16px; }

/* Responsive Adjustments for Reels and Graphics */
@media (max-width: 1024px) {
  .graphics-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 768px) {
  .reels-carousel-track-wrapper {
    scroll-padding-inline: calc(50% - 130px);
  }
  .reels-carousel-track {
    gap: 16px;
  }
  .reel-card {
    flex: 0 0 260px;
    width: 260px;
  }
  .graphics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
  }
  .lightbox-content-wrap {
    max-height: 95vh;
  }
  .lightbox-body {
    max-height: 60vh;
  }
  .lightbox-meta-bar {
    padding: 14px 18px;
  }
}

@media (max-width: 480px) {
  .reels-carousel-track-wrapper {
    scroll-padding-inline: calc(50% - 120px);
  }
  .reel-card {
    flex: 0 0 240px;
    width: 240px;
  }
  .reels-carousel-footer {
    flex-direction: column;
    gap: 14px;
  }
}

@media (max-width: 360px) {
  .reels-carousel-track-wrapper {
    scroll-padding-inline: calc(50% - 110px);
  }
  .reel-card {
    flex: 0 0 220px;
    width: 220px;
    border-radius: 20px;
  }
  .reel-frame-inner {
    border-radius: 19px;
  }
  .reel-play-btn {
    width: 54px;
    height: 54px;
  }
  .reel-play-btn svg {
    width: 22px;
    height: 22px;
  }
  .reel-meta-title {
    font-size: 0.95rem;
  }
}

body.script:
//
(function(){
  /* ==========================================================================
     STUDIO CONFIGURATION
     Central authoritative configuration for Singh Creative Studio.
     Replace or customize any of these values as needed.
     ========================================================================== */
  var STUDIO_CONFIG = {
    brandName: 'Singh Creative Studio',
    founder: 'Mukesh Singh',
    tagline: 'Ideas Made Visible.',
    email: 'dharmjeetsingh958@gmail.com',
    phone: '+919334603912',
    phoneDisplay: '+91 9334603912',
    quoteTarget: '#contact',
    social: {
      instagram: 'https://www.instagram.com/getsynfusion/',
      facebook: 'https://www.facebook.com/getsynfusion',
      youtube: 'https://www.youtube.com/@getsynfusion',
      whatsapp: 'https://wa.me/919334603912'
    },
    bloggerFeed: {
      postsUrl: '/feeds/posts/default?alt=json',
      reelsLabel: 'reels',
      graphicsLabel: 'graphics',
      maxResultsPerPage: 50,
      maxTotalPosts: 150
    },
    youtubePlayerVars: {
      autoplay: 0,
      controls: 1,
      modestbranding: 1,
      rel: 0,
      playsinline: 1
    }
  };

  // Cinematic Intro Screen handling with Explicit State Machine:
  // States: 'intro-active' -> 'intro-transitioning' -> 'intro-complete'
  var intro = document.getElementById('introScreen');
  var enterBtn = document.getElementById('enterStudio');
  var introState = 'intro-active';
  var introFallbackTimer = null;

  // Ensure scroll is at top and locked while intro is active
  if (intro && !intro.classList.contains('hidden')) {
    document.body.classList.remove('intro-dismissed');
    document.body.style.overflow = 'hidden';
    window.scrollTo(0, 0);
  }

  function finishIntroTransition() {
    if (introState === 'intro-complete') return;
    introState = 'intro-complete';

    if (introFallbackTimer) {
      clearTimeout(introFallbackTimer);
      introFallbackTimer = null;
    }

    if (intro) {
      intro.classList.remove('transitioning');
      intro.classList.add('hidden');
      intro.setAttribute('aria-hidden', 'true');
    }

    document.body.classList.add('intro-dismissed');
    document.body.style.overflow = '';
    window.scrollTo(0, 0);
  }

  function startCinematicTransition() {
    if (introState !== 'intro-active') return;
    introState = 'intro-transitioning';

    if (enterBtn) {
      enterBtn.classList.add('active-cta');
      enterBtn.setAttribute('disabled', 'disabled');
    }

    var prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (prefersReducedMotion) {
      finishIntroTransition();
      return;
    }

    if (intro) {
      intro.classList.add('transitioning');
      var onTransitionEnd = function(e) {
        if (e.target === intro) {
          intro.removeEventListener('transitionend', onTransitionEnd);
          finishIntroTransition();
        }
      };
      intro.addEventListener('transitionend', onTransitionEnd);
    }

    // Safety fallback timer in case transitionend does not fire
    introFallbackTimer = setTimeout(finishIntroTransition, 1000);
  }

  if (enterBtn) {
    enterBtn.addEventListener('click', function(e) {
      e.preventDefault();
      startCinematicTransition();
    });
  }

  // Mobile Navigation Toggle
  var menuBtn = document.getElementById('menuToggle');
  var navLinks = document.getElementById('navLinks');

  if (menuBtn && navLinks) {
    menuBtn.addEventListener('click', function(){
      var isOpen = navLinks.classList.toggle('open');
      menuBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });

    navLinks.querySelectorAll('a').forEach(function(link){
      link.addEventListener('click', function(){
        navLinks.classList.remove('open');
        menuBtn.setAttribute('aria-expanded', 'false');
      });
    });
  }

  // Automatic Visual Carousel
  var scenes = [].slice.call(document.querySelectorAll('.scene'));
  var carouselTitle = document.getElementById('carouselTitle');
  var carouselSub = document.getElementById('carouselSub');
  var carouselProgress = document.getElementById('carouselProgress');
  var btnPrev = document.getElementById('carouselPrev');
  var btnNext = document.getElementById('carouselNext');
  var btnToggle = document.getElementById('carouselToggle');
  var togglePauseIcon = document.getElementById('togglePauseIcon');

  var curIdx = 0;
  var timer = null;
  var isPaused = false;
  var intervalMs = 4000;
  var prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function setProgress(percent) {
    if (carouselProgress) {
      carouselProgress.style.width = percent + '%';
    }
  }

  function showSlide(idx) {
    if (!scenes.length) return;
    curIdx = (idx + scenes.length) % scenes.length;
    scenes.forEach(function(s, i) {
      s.classList.toggle('active', i === curIdx);
    });

    var activeScene = scenes[curIdx];
    if (activeScene) {
      if (carouselTitle) carouselTitle.textContent = activeScene.getAttribute('data-title') || '';
      if (carouselSub) carouselSub.textContent = activeScene.getAttribute('data-sub') || '';
    }

    setProgress(((curIdx + 1) / scenes.length) * 100);
  }

  function startCarousel() {
    stopCarousel();
    if (!isPaused && !prefersReducedMotion && !document.hidden) {
      timer = setInterval(function(){
        showSlide(curIdx + 1);
      }, intervalMs);
    }
  }

  function stopCarousel() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  }

  if (scenes.length) {
    showSlide(0);
    startCarousel();

    if (btnPrev) {
      btnPrev.addEventListener('click', function(){
        showSlide(curIdx - 1);
        startCarousel();
      });
    }

    if (btnNext) {
      btnNext.addEventListener('click', function(){
        showSlide(curIdx + 1);
        startCarousel();
      });
    }

    if (btnToggle) {
      btnToggle.addEventListener('click', function(){
        isPaused = !isPaused;
        btnToggle.setAttribute('aria-label', isPaused ? 'Play carousel' : 'Pause carousel');
        if (togglePauseIcon) {
          togglePauseIcon.innerHTML = isPaused ?
            "<polygon points='5 3 19 12 5 21 5 3'/>" :
            "<rect x='6' y='4' width='4' height='16'/><rect x='14' y='4' width='4' height='16'/>";
        }
        if (isPaused) stopCarousel();
        else startCarousel();
      });
    }

    var visualCanvas = document.getElementById('visualCanvas');
    if (visualCanvas) {
      visualCanvas.addEventListener('mouseenter', stopCarousel);
      visualCanvas.addEventListener('mouseleave', function(){
        if (!isPaused) startCarousel();
      });

      var touchStartX = 0;
      visualCanvas.addEventListener('touchstart', function(e){
        if (e.touches.length) touchStartX = e.touches[0].clientX;
      }, {passive: true});

      visualCanvas.addEventListener('touchend', function(e){
        if (e.changedTouches.length) {
          var diff = e.changedTouches[0].clientX - touchStartX;
          if (Math.abs(diff) > 40) {
            showSlide(curIdx + (diff < 0 ? 1 : -1));
            startCarousel();
          }
        }
      }, {passive: true});
    }

    document.addEventListener('visibilitychange', function(){
      if (document.hidden) stopCarousel();
      else if (!isPaused) startCarousel();
    });
  }

  // Portfolio Filter handling
  var filterButtons = document.querySelectorAll('.filter');
  var projectCards = document.querySelectorAll('.project');

  filterButtons.forEach(function(btn){
    btn.addEventListener('click', function(){
      var filterValue = btn.getAttribute('data-filter');

      filterButtons.forEach(function(b){ b.classList.remove('active'); });
      btn.classList.add('active');

      projectCards.forEach(function(card){
        var tags = (card.getAttribute('data-tags') || '').split(' ');
        if (filterValue === 'all' || tags.indexOf(filterValue) !== -1) {
          card.removeAttribute('hidden');
        } else {
          card.setAttribute('hidden', 'hidden');
        }
      });
    });
  });

  // Intersection Observer for Section Reveals
  if ('IntersectionObserver' in window) {
    var observer = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting) {
          e.target.classList.add('visible');
          observer.unobserve(e.target);
        }
      });
    }, { threshold: 0.1 });

    document.querySelectorAll('.reveal').forEach(function(el){
      observer.observe(el);
    });
  } else {
    document.querySelectorAll('.reveal').forEach(function(el){
      el.classList.add('visible');
    });
  }

  if (prefersReducedMotion) {
    document.querySelectorAll('.reveal').forEach(function(el){
      el.classList.add('visible');
    });
  }

  // Dynamic Year
  var yearEl = document.getElementById('yearNow');
  if (yearEl) {
    yearEl.textContent = new Date().getFullYear();
  }

  /* ==========================================================================
     SINGH CREATIVE STUDIO — REELS & GRAPHICS SYSTEM
     ========================================================================== */

  /**
   * REELS DATA CONFIGURATION
   * To add a new vertical video reel, add an object to this array with:
   * - id: Unique string or number
   * - title: Project name
   * - category: '2d' | '3d' | 'editing' | 'ai-ads' | 'motion'
   * - youtubeId: Valid 11-character YouTube Video ID (e.g., 'dQw4w9WgXcQ')
   * - thumbnail: Optional custom thumbnail image URL (if omitted, uses YouTube HD thumbnail fallback)
   * - description: Short project breakdown
   * - featured: true/false
   */
  var REELS_DATA = []; // Live published Blogger posts only; no demo reels.

  /**
   * GRAPHIC DESIGN SHOWCASE DATA CONFIGURATION
   * To add a new graphic design project, add an object to this array:
   * - id: Unique identifier
   * - title: Project title
   * - category: 'logo' | 'social' | 'thumbnail' | 'poster' | 'ads' | 'brand'
   * - categoryLabel: Human readable label (e.g. 'YouTube Thumbnail')
   * - image: High-res image URL or inline SVG placeholder
   * - badge: 'CONCEPT' | 'CLIENT' | 'FEATURED'
   */
  var GRAPHICS_DATA = [];

  // Global YouTube API Management Variables
  var ytApiLoaded = false;
  var ytApiLoading = false;
  var activeYtPlayer = null;
  var activeYtIframeId = null;
  var isMuted = false;

  // Smart Reel Playback State Management
  // Tracks per-reel playback state to support visibility-based auto-pause/resume
  var reelPlaybackStates = {};
  var activePlayingReelId = null;
  var isAutoPausingOrResuming = false;
  var reelsIntersectionObserver = null;

  function getReelPlaybackState(reelId) {
    if (!reelPlaybackStates[reelId]) {
      reelPlaybackStates[reelId] = {
        reelId: reelId,
        wasPlayingBeforeHidden: false,
        isAutoPaused: false,
        isManuallyPaused: false,
        isPlaying: false,
        isReady: false,
        resumePending: false,
        player: null,
        containerId: null,
        index: -1
      };
    }
    return reelPlaybackStates[reelId];
  }


  // Active Reels Carousel State
  var filteredReels = REELS_DATA.slice();
  var activeReelIndex = 0;
  var isCarouselProgrammaticScroll = false;
  var carouselProgrammaticTimer = null;

  // Registered callbacks waiting for YouTube API ready
  var ytReadyCallbacks = [];

  // Helper to load YouTube IFrame API safely, idempotently, and without multiple script injections
  function loadYouTubeIframeApi(callback) {
    if (window.YT && typeof window.YT.Player === 'function') {
      ytApiLoaded = true;
      if (typeof callback === 'function') callback();
      return;
    }

    if (typeof callback === 'function') {
      ytReadyCallbacks.push(callback);
    }

    if (ytApiLoading) return;
    ytApiLoading = true;

    // Preserve any existing window.onYouTubeIframeAPIReady handler
    var existingHandler = window.onYouTubeIframeAPIReady;
    window.onYouTubeIframeAPIReady = function() {
      ytApiLoaded = true;
      ytApiLoading = false;
      if (typeof existingHandler === 'function') {
        try { existingHandler(); } catch (e) {}
      }
      while (ytReadyCallbacks.length) {
        var cb = ytReadyCallbacks.shift();
        try { cb(); } catch (e) {}
      }
    };

    // Check if script tag is already in DOM
    var existingScript = document.querySelector('script[src*="youtube.com/iframe_api"]');
    if (!existingScript) {
      var tag = document.createElement('script');
      tag.src = 'https://www.youtube.com/iframe_api';
      tag.async = true;
      var firstScript = document.getElementsByTagName('script')[0];
      if (firstScript && firstScript.parentNode) {
        firstScript.parentNode.insertBefore(tag, firstScript);
      } else {
        (document.head || document.body).appendChild(tag);
      }
    }
  }

  // Centralized YouTube Player Cleanup & Stop
  function cleanupActivePlayer(options) {
    var opts = options || {};
    var preserveState = opts.preserveState === true;

    if (activePlayingReelId && !preserveState) {
      var oldState = getReelPlaybackState(activePlayingReelId);
      oldState.isPlaying = false;
      oldState.wasPlayingBeforeHidden = false;
      oldState.isAutoPaused = false;
      oldState.isManuallyPaused = false;
      oldState.isReady = false;
      oldState.resumePending = false;
      oldState.player = null;
    }

    if (activeYtPlayer) {
      try {
        if (typeof activeYtPlayer.stopVideo === 'function') {
          activeYtPlayer.stopVideo();
        }
        if (typeof activeYtPlayer.destroy === 'function') {
          activeYtPlayer.destroy();
        }
      } catch (e) {}
      activeYtPlayer = null;
    }
    activeYtIframeId = null;
    if (!preserveState) {
      activePlayingReelId = null;
    }

    // Reset iframe containers visually
    var iframeContainers = document.querySelectorAll('.reel-iframe-container');
    iframeContainers.forEach(function(el) {
      el.innerHTML = '';
    });

    var thumbWraps = document.querySelectorAll('.reel-thumbnail-wrap');
    thumbWraps.forEach(function(el) {
      el.style.opacity = '1';
      el.style.pointerEvents = 'auto';
    });

    var statusOverlays = document.querySelectorAll('.reel-status-overlay');
    statusOverlays.forEach(function(el) {
      el.classList.add('hidden');
    });
  }

  // Render SVG Thumbnail Fallback
  function createBrandedSvgThumbnail(title, category) {
    var catUpper = (category || 'CREATIVE REEL').toUpperCase();
    var cleanTitle = (title || 'Singh Creative Studio').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(
      "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 360 640'>" +
      "<defs><linearGradient id='g' x1='0' y1='0' x2='1' y2='1'>" +
      "<stop stop-color='#0F172A'/><stop offset='0.5' stop-color='#1E1B4B'/><stop offset='1' stop-color='#312E81'/>" +
      "</linearGradient></defs>" +
      "<rect width='360' height='640' fill='url(#g)'/>" +
      "<circle cx='180' cy='280' r='100' fill='none' stroke='#4F46E5' stroke-width='2' stroke-opacity='0.4'/>" +
      "<text x='180' y='220' text-anchor='middle' fill='#818CF8' font-family='sans-serif' font-size='12' font-weight='800' letter-spacing='3'>" + catUpper + "</text>" +
      "<text x='180' y='280' text-anchor='middle' fill='#FFFFFF' font-family='sans-serif' font-size='22' font-weight='800'>" + cleanTitle + "</text>" +
      "<text x='180' y='580' text-anchor='middle' fill='#94A3B8' font-family='sans-serif' font-size='11' letter-spacing='2'>SINGH CREATIVE STUDIO</text>" +
      "</svg>"
    );
  }

  // Global handler for Reel Cover Image Fallback progression
  window.handleReelCoverImgError = function(imgEl) {
    if (!imgEl) return;
    var step = parseInt(imgEl.getAttribute("data-fallback-step") || "0", 10);
    var ytId = imgEl.getAttribute("data-yt-id") || "";
    var title = imgEl.getAttribute("data-title") || "Singh Creative Studio";
    var cat = imgEl.getAttribute("data-category") || "CREATIVE REEL";

    if (step === 0) {
      imgEl.setAttribute("data-fallback-step", "1");
      if (ytId) {
        if (imgEl.src.indexOf("maxresdefault.jpg") !== -1) {
          imgEl.setAttribute("data-fallback-step", "2");
          imgEl.src = "https://i.ytimg.com/vi/" + ytId + "/hqdefault.jpg";
        } else {
          imgEl.src = "https://i.ytimg.com/vi/" + ytId + "/maxresdefault.jpg";
        }
      } else {
        imgEl.setAttribute("data-fallback-step", "4");
        imgEl.src = createBrandedSvgThumbnail(title, cat);
      }
    } else if (step === 1) {
      imgEl.setAttribute("data-fallback-step", "2");
      if (ytId) {
        imgEl.src = "https://i.ytimg.com/vi/" + ytId + "/hqdefault.jpg";
      } else {
        imgEl.setAttribute("data-fallback-step", "4");
        imgEl.src = createBrandedSvgThumbnail(title, cat);
      }
    } else if (step === 2) {
      imgEl.setAttribute("data-fallback-step", "3");
      if (ytId) {
        imgEl.src = "https://i.ytimg.com/vi/" + ytId + "/mqdefault.jpg";
      } else {
        imgEl.setAttribute("data-fallback-step", "4");
        imgEl.src = createBrandedSvgThumbnail(title, cat);
      }
    } else if (step === 3) {
      imgEl.setAttribute("data-fallback-step", "4");
      imgEl.src = createBrandedSvgThumbnail(title, cat);
    } else {
      imgEl.onerror = null;
    }
  };

  // Feed loading and error state management
  var bloggerFeedState = {
    isLoading: true,
    reelsError: false,
    graphicsError: false,
    reelsErrorMsg: '',
    graphicsErrorMsg: '',
    hasLoadedOnce: false
  };

  // Safe HTML Escaping and Entity Decoding
  function escapeHtml(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function decodeHtmlEntities(str) {
    if (!str) return '';
    var txt = document.createElement('textarea');
    txt.innerHTML = str;
    return txt.value;
  }

  // Extract YouTube ID from text, links, query params, or iframes
  function extractYouTubeIdFromText(text) {
    if (!text) return null;
    var rawText = decodeHtmlEntities(text);
    // 1. YouTube watch URL with query parameters (v=...)
    var watchMatch = rawText.match(/(?:https?:\/\/)?(?:www\.|m\.)?youtube\.com\/watch\?[^"'\s<>#]*\bv=([a-zA-Z0-9_-]{11})/i);
    if (watchMatch) return watchMatch[1];
    // 2. YouTube Shorts URL
    var shortsMatch = rawText.match(/(?:https?:\/\/)?(?:www\.|m\.)?youtube\.com\/shorts\/([a-zA-Z0-9_-]{11})/i);
    if (shortsMatch) return shortsMatch[1];
    // 3. YouTube Embed URL or iframe src
    var embedMatch = rawText.match(/(?:https?:\/\/)?(?:www\.|m\.)?youtube\.com\/embed\/([a-zA-Z0-9_-]{11})/i);
    if (embedMatch) return embedMatch[1];
    // 4. youtu.be shortlink
    var youtbeMatch = rawText.match(/(?:https?:\/\/)?youtu\.be\/([a-zA-Z0-9_-]{11})/i);
    if (youtbeMatch) return youtbeMatch[1];
    // 5. Iframe tag fallback
    var iframeMatch = rawText.match(/<iframe[^>]+src=["']([^"']+)["']/i);
    if (iframeMatch) {
      var iframeSrc = iframeMatch[1];
      var idFromSrc = extractYouTubeIdFromText(iframeSrc);
      if (idFromSrc) return idFromSrc;
    }
    return null;
  }

  // Upgrade Blogger image URLs to high-resolution
  function upgradeBloggerImageUrl(url) {
    if (!url) return '';
    // Decode HTML entities if present
    url = decodeHtmlEntities(url).trim();
    // Replace Blogger size modifier with high-res /s1600/ or /w1600/
    if (/blogger\.googleusercontent\.com|bp\.blogspot\.com|googleusercontent\.com/i.test(url)) {
      url = url.replace(/\/(s\d+(-[chw\d]+)?|w\d+(-h\d+)?)\//, '/s1600/');
    }
    return url;
  }

  // Extract all valid image URLs from HTML content
  function extractImagesFromContent(contentHtml) {
    if (!contentHtml) return [];
    var images = [];
    var raw = decodeHtmlEntities(contentHtml);
    // Find anchor wrapped images: <a href="...image.jpg"><img src="..."/></a>
    var aImgRegex = /<a[^>]+href=["']([^"']+\.(?:jpe?g|png|webp|gif|svg)(?:\?[^"']*)?)["'][^>]*>\s*<img/gi;
    var aMatch;
    while ((aMatch = aImgRegex.exec(raw)) !== null) {
      images.push(upgradeBloggerImageUrl(aMatch[1]));
    }
    // Find all <img> tags
    var imgRegex = /<img[^>]+src=["']([^"']+)["']/gi;
    var imgMatch;
    while ((imgMatch = imgRegex.exec(raw)) !== null) {
      var src = upgradeBloggerImageUrl(imgMatch[1]);
      if (src && !images.includes(src)) {
        images.push(src);
      }
    }
    return images;
  }

  // Render Reels Carousel Track
  function renderReelsCarousel() {
    var track = document.getElementById('reelsTrack');
    var counterEl = document.getElementById('reelsCounter');
    if (!track) return;

    // Clean up active playback before re-rendering
    cleanupActivePlayer();

    // Check loading state
    if (bloggerFeedState.isLoading && !bloggerFeedState.hasLoadedOnce && !filteredReels.length) {
      track.innerHTML = "<div style='padding: 60px 24px; text-align: center; color: var(--muted); width: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center;'>" +
        "<div class='reel-spinner' style='display: block; margin: 0 auto 16px;'></div>" +
        "<div style='font-size: 0.95rem; font-weight: 500;'>Loading published reels...</div>" +
        "</div>";
      if (counterEl) counterEl.innerHTML = "-- <span>/ --</span>";
      return;
    }

    // Check error state
    if (bloggerFeedState.reelsError && !filteredReels.length) {
      track.innerHTML = "<div style='padding: 50px 24px; text-align: center; color: var(--muted); width: 100%; max-width: 500px; margin: 0 auto;'>" +
        "<svg xmlns='http://www.w3.org/2000/svg' width='40' height='40' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round' stroke-linejoin='round' style='margin: 0 auto 16px; opacity: 0.6;'><circle cx='12' cy='12' r='10'/><line x1='12' y1='8' x2='12' y2='12'/><line x1='12' y1='16' x2='12.01' y2='16'/></svg>" +
        "<div style='font-size: 1.05rem; font-weight: 600; color: var(--text); margin-bottom: 8px;'>Unable to Load Reels</div>" +
        "<p style='font-size: 0.88rem; margin-bottom: 20px;'>" + escapeHtml(bloggerFeedState.reelsErrorMsg || 'Could not fetch reels from Blogger feed.') + "</p>" +
        "<button id='reelsRetryBtn' type='button' class='btn btn-primary' style='padding: 8px 20px; font-size: 0.85rem;'>Retry</button>" +
        "</div>";
      var retryBtn = document.getElementById('reelsRetryBtn');
      if (retryBtn) {
        retryBtn.addEventListener('click', function() {
          discoverBloggerPosts();
        });
      }
      if (counterEl) counterEl.innerHTML = "00 <span>/ 00</span>";
      return;
    }

    if (!filteredReels.length) {
      track.innerHTML = "<div style='padding: 60px 24px; text-align: center; color: var(--muted); width: 100%; max-width: 480px; margin: 0 auto;'>" +
        "<svg xmlns='http://www.w3.org/2000/svg' width='40' height='40' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round' style='margin: 0 auto 16px; opacity: 0.5;'><rect width='18' height='18' x='3' y='3' rx='2' ry='2'/><polyline points='11 3 11 11 14 8 17 11 17 3'/></svg>" +
        "<div style='font-size: 1rem; font-weight: 600; color: var(--text); margin-bottom: 8px;'>No Reels Published Yet</div>" +
        "<p style='font-size: 0.88rem;'>Publish posts with the label <strong>'Reels'</strong> or YouTube video links on Blogger to automatically populate this section.</p>" +
        "</div>";
      if (counterEl) counterEl.innerHTML = "00 <span>/ 00</span>";
      return;
    }

    if (activeReelIndex >= filteredReels.length) activeReelIndex = 0;
    if (activeReelIndex < 0) activeReelIndex = filteredReels.length - 1;

    var html = '';
    filteredReels.forEach(function(reel, idx) {
      var isActive = idx === activeReelIndex;
      var thumbUrl = reel.thumbnail || ('https://i.ytimg.com/vi/' + reel.youtubeId + '/maxresdefault.jpg');
      var safeTitle = escapeHtml(reel.title);
      var badgeText = (reel.categoryLabel || reel.category || 'REEL').toUpperCase();

      html += "<div class='reel-card " + (isActive ? 'active' : '') + "' data-index='" + idx + "' data-id='" + reel.id + "'>";
      html += "<div class='reel-frame-inner'>";

      // Thumbnail Overlay with real <img> cover and fallback progression
      html += "<div class='reel-thumbnail-wrap' id='reelThumb-" + idx + "'>";
      html += "<img class='reel-cover-img' src='" + thumbUrl + "' alt='" + safeTitle + "' data-fallback-step='0' data-yt-id='" + (reel.youtubeId || '') + "' data-title='" + safeTitle + "' data-category='" + badgeText + "' onerror='window.handleReelCoverImgError(this);' loading='lazy' />";
      html += "<span class='reel-badge-category'>" + badgeText + "</span>";
      html += "<div class='reel-play-btn-wrap' data-play-index='" + idx + "' title='Play Reel'>";
      html += "<div class='reel-play-btn'><svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><polygon points='5 3 19 12 5 21 5 3'/></svg></div>";
      html += "</div>";
      html += "<div class='reel-meta-bottom'>";
      html += "<div class='reel-meta-title'>" + safeTitle + "</div>";
      html += "<div class='reel-meta-desc'>" + (reel.description ? escapeHtml(reel.description) : safeTitle) + "</div>";
      html += "</div></div>";

      // Iframe Container
      html += "<div class='reel-iframe-container' id='reelIframeBox-" + idx + "'></div>";

      // Status Overlay (Loading/Error)
      html += "<div class='reel-status-overlay hidden' id='reelStatus-" + idx + "'>";
      html += "<div class='reel-spinner'></div>";
      html += "<div class='reel-error-text' id='reelErrorText-" + idx + "'>Loading YouTube Player...</div>";
      html += "<button class='reel-retry-btn hidden' id='reelRetry-" + idx + "' type='button'>Retry Playback</button>";
      html += "</div>";

      html += "</div></div>";
    });

    track.innerHTML = html;

    if (counterEl) {
      var numStr = (activeReelIndex + 1 < 10 ? '0' : '') + (activeReelIndex + 1);
      var totalStr = (filteredReels.length < 10 ? '0' : '') + filteredReels.length;
      counterEl.innerHTML = numStr + " <span>/ " + totalStr + "</span>";
    }

    // Attach click events to cards & play buttons
    var cardEls = track.querySelectorAll('.reel-card');
    cardEls.forEach(function(cardEl) {
      var idx = parseInt(cardEl.getAttribute('data-index'), 10);

      cardEl.addEventListener('click', function(e) {
        var playBtn = e.target.closest('.reel-play-btn-wrap');
        if (playBtn) {
          if (idx !== activeReelIndex) {
            selectReel(idx, { smooth: true });
          }
          playReel(idx);
        } else {
          selectReel(idx, { smooth: true });
        }
      });
    });
  }

  function selectReel(index, options) {
    if (!filteredReels.length) return;
    if (index < 0) index = 0;
    if (index >= filteredReels.length) index = filteredReels.length - 1;

    var opts = options || {};
    var isSmooth = opts.smooth !== false;

    if (index !== activeReelIndex) {
      cleanupActivePlayer();
      activeReelIndex = index;
    }

    var cards = document.querySelectorAll('#reelsTrack .reel-card');
    cards.forEach(function(card, idx) {
      card.classList.toggle('active', idx === activeReelIndex);
    });

    var counterEl = document.getElementById('reelsCounter');
    if (counterEl) {
      var numStr = (activeReelIndex + 1 < 10 ? '0' : '') + (activeReelIndex + 1);
      var totalStr = (filteredReels.length < 10 ? '0' : '') + filteredReels.length;
      counterEl.innerHTML = numStr + " <span>/ " + totalStr + "</span>";
    }

    // Scroll selected card to exact horizontal center strictly inside the wrapper container
    // Do NOT use targetCard.scrollIntoView() which causes unwanted document-level vertical scrolling!
    var targetCard = cards[activeReelIndex];
    var wrapper = document.getElementById('reelsTrackWrapper');
    if (targetCard && wrapper) {
      var cardOffset = targetCard.offsetLeft + (targetCard.offsetWidth / 2) - (wrapper.clientWidth / 2);
      var targetLeft = Math.max(0, cardOffset);

      if (Math.abs(wrapper.scrollLeft - targetLeft) > 2) {
        isCarouselProgrammaticScroll = true;
        clearTimeout(carouselProgrammaticTimer);
        carouselProgrammaticTimer = setTimeout(function() {
          isCarouselProgrammaticScroll = false;
        }, isSmooth ? 500 : 50);

        if (typeof wrapper.scrollTo === 'function') {
          wrapper.scrollTo({
            left: targetLeft,
            behavior: isSmooth ? 'smooth' : 'auto'
          });
        } else {
          wrapper.scrollLeft = targetLeft;
        }
      }
    }
  }

  function playReel(index, options) {
    var reel = filteredReels[index];
    if (!reel || !reel.youtubeId) return;

    var opts = options || {};
    var isResume = opts.isResume === true;
    var reelId = reel.id;
    var state = getReelPlaybackState(reelId);
    state.index = index;

    // If this Reel is already active and playing, toggle pause (manual user action)
    if (!isResume && activePlayingReelId === reelId && activeYtPlayer) {
      if (typeof activeYtPlayer.getPlayerState === 'function') {
        var currentState = activeYtPlayer.getPlayerState();
        if (window.YT && window.YT.PlayerState) {
          if (currentState === window.YT.PlayerState.PLAYING || currentState === window.YT.PlayerState.BUFFERING) {
            // Manual user pause: clear auto-pause intent so it stays paused when scrolling
            state.wasPlayingBeforeHidden = false;
            state.isAutoPaused = false;
            state.isManuallyPaused = true;
            state.isPlaying = false;
            try {
              activeYtPlayer.pauseVideo();
            } catch (err) {}
            var currentThumb = document.getElementById('reelThumb-' + index);
            if (currentThumb) {
              currentThumb.style.opacity = '1';
              currentThumb.style.pointerEvents = 'auto';
            }
            return;
          } else if (currentState === window.YT.PlayerState.PAUSED) {
            // Manual user resume
            state.wasPlayingBeforeHidden = false;
            state.isAutoPaused = false;
            state.isManuallyPaused = false;
            state.isPlaying = true;
            var currentThumbWrap = document.getElementById('reelThumb-' + index);
            if (currentThumbWrap) {
              currentThumbWrap.style.opacity = '0';
              currentThumbWrap.style.pointerEvents = 'none';
            }
            try {
              activeYtPlayer.playVideo();
            } catch (err) {}
            return;
          }
        }
      }
    }

    // If starting a different reel or starting fresh, cleanup any other playing reel
    if (activePlayingReelId && activePlayingReelId !== reelId) {
      var prevReelState = getReelPlaybackState(activePlayingReelId);
      prevReelState.isPlaying = false;
      prevReelState.wasPlayingBeforeHidden = false;
      prevReelState.isAutoPaused = false;
      prevReelState.isManuallyPaused = false;
      prevReelState.resumePending = false;
      prevReelState.isReady = false;
      prevReelState.player = null;
      cleanupActivePlayer({ preserveState: false });
    }

    // Set as currently intended playing reel
    activePlayingReelId = reelId;
    state.isManuallyPaused = false;
    state.isPlaying = true;
    if (!isResume) {
      state.wasPlayingBeforeHidden = false;
      state.isAutoPaused = false;
    }

    var iframeBox = document.getElementById('reelIframeBox-' + index);
    var thumbWrap = document.getElementById('reelThumb-' + index);
    var statusOverlay = document.getElementById('reelStatus-' + index);
    var errorText = document.getElementById('reelErrorText-' + index);
    var retryBtn = document.getElementById('reelRetry-' + index);

    if (!iframeBox) return;

    // If player instance already exists and is ready, resume without reloading iframe
    if (activeYtPlayer && state.containerId === 'ytPlayerInstance-' + index && state.isReady) {
      if (thumbWrap) {
        thumbWrap.style.opacity = '0';
        thumbWrap.style.pointerEvents = 'none';
      }
      try {
        if (isMuted && typeof activeYtPlayer.mute === 'function') activeYtPlayer.mute();
        activeYtPlayer.playVideo();
      } catch (err) {
        if (statusOverlay) {
          statusOverlay.classList.remove('hidden');
          if (errorText) errorText.textContent = "Unable to resume playback. Tap play button to start.";
        }
      }
      return;
    }

    // Show loading overlay
    if (statusOverlay) {
      statusOverlay.classList.remove('hidden');
      if (errorText) errorText.textContent = "Connecting to YouTube...";
      if (retryBtn) retryBtn.classList.add('hidden');
    }

    state.resumePending = true;

    loadYouTubeIframeApi(function() {
      // If another reel was clicked while loading, abort
      if (activePlayingReelId !== reelId || activeReelIndex !== index) {
        state.resumePending = false;
        return;
      }

      cleanupActivePlayer({ preserveState: true });
      activePlayingReelId = reelId;

      var containerId = 'ytPlayerInstance-' + index;
      state.containerId = containerId;
      iframeBox.innerHTML = "<div id='" + containerId + "'></div>";

      if (statusOverlay) statusOverlay.classList.add('hidden');

      try {
        var pVars = Object.assign({}, STUDIO_CONFIG.youtubePlayerVars, {
          mute: isMuted ? 1 : 0
        });

        activeYtPlayer = new window.YT.Player(containerId, {
          height: '100%',
          width: '100%',
          videoId: reel.youtubeId,
          playerVars: pVars,
          events: {
            onReady: function(event) {
              state.isReady = true;
              state.resumePending = false;
              state.player = event.target;
              activeYtIframeId = containerId;

              // Ensure this is still the active reel before playing
              if (activePlayingReelId === reelId) {
                if (thumbWrap) {
                  thumbWrap.style.opacity = '0';
                  thumbWrap.style.pointerEvents = 'none';
                }
                try {
                  event.target.playVideo();
                } catch (playErr) {
                  // Browser autoplay restriction handling
                  if (statusOverlay) {
                    statusOverlay.classList.remove('hidden');
                    if (errorText) errorText.textContent = "Autoplay restricted. Tap play to view.";
                  }
                }
              }
            },
            onStateChange: function(event) {
              if (!window.YT || !window.YT.PlayerState) return;

              if (event.data === window.YT.PlayerState.PLAYING) {
                state.isPlaying = true;
                state.isManuallyPaused = false;
                state.isAutoPaused = false;
                if (thumbWrap) {
                  thumbWrap.style.opacity = '0';
                  thumbWrap.style.pointerEvents = 'none';
                }
              } else if (event.data === window.YT.PlayerState.PAUSED) {
                state.isPlaying = false;
                // If this pause was not triggered automatically by scrolling, mark as manual pause
                if (!isAutoPausingOrResuming) {
                  state.isManuallyPaused = true;
                  state.wasPlayingBeforeHidden = false;
                  state.isAutoPaused = false;
                  if (thumbWrap) {
                    thumbWrap.style.opacity = '1';
                    thumbWrap.style.pointerEvents = 'auto';
                  }
                }
              } else if (event.data === window.YT.PlayerState.ENDED) {
                // When finished, do not loop or start next reel
                state.isPlaying = false;
                state.wasPlayingBeforeHidden = false;
                state.isAutoPaused = false;
                state.isManuallyPaused = false;
                state.resumePending = false;
                cleanupActivePlayer({ preserveState: false });
              }
            },
            onError: function(e) {
              state.isPlaying = false;
              state.resumePending = false;
              if (statusOverlay) {
                statusOverlay.classList.remove('hidden');
                var msg = "Video unavailable or embedding restricted.";
                if (e && e.data === 150) msg = "Playback restricted by video owner.";
                if (errorText) errorText.textContent = msg;
                if (retryBtn) {
                  retryBtn.classList.remove('hidden');
                  retryBtn.onclick = function() {
                    playReel(index);
                  };
                }
              }
            }
          }
        });
      } catch (err) {
        state.resumePending = false;
        if (statusOverlay) {
          statusOverlay.classList.remove('hidden');
          if (errorText) errorText.textContent = "Unable to initialize YouTube API player.";
        }
      }
    });
  }

  // Setup Reels Controls & Touch Gestures
  function setupReelsControls() {
    var prevBtn = document.getElementById('reelPrevBtn');
    var nextBtn = document.getElementById('reelNextBtn');
    var muteBtn = document.getElementById('reelMuteBtn');
    var muteIcon = document.getElementById('reelMuteIcon');
    var filterBtns = document.querySelectorAll('#reelsFilterGroup .reel-filter-btn');

    if (prevBtn) {
      prevBtn.addEventListener('click', function() {
        if (!filteredReels.length) return;
        var newIdx = (activeReelIndex - 1 + filteredReels.length) % filteredReels.length;
        selectReel(newIdx);
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function() {
        if (!filteredReels.length) return;
        var newIdx = (activeReelIndex + 1) % filteredReels.length;
        selectReel(newIdx);
      });
    }

    if (muteBtn) {
      muteBtn.addEventListener('click', function() {
        isMuted = !isMuted;
        muteBtn.setAttribute('title', isMuted ? 'Unmute' : 'Mute');
        if (activeYtPlayer && typeof activeYtPlayer.mute === 'function') {
          if (isMuted) activeYtPlayer.mute();
          else activeYtPlayer.unMute();
        }
        if (muteIcon) {
          muteIcon.innerHTML = isMuted ?
            "<polygon points='11 5 6 9 2 9 2 15 6 15 11 19 11 5'/><line x1='23' x2='17' y1='9' y2='15'/><line x1='17' x2='23' y1='9' y2='15'/>" :
            "<polygon points='11 5 6 9 2 9 2 15 6 15 11 19 11 5'/><path d='M15.54 8.46a5 5 0 0 1 0 7.07'/><path d='M19.07 4.93a10 10 0 0 1 0 14.14'/>";
        }
      });
    }

    filterBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        var category = btn.getAttribute('data-reel-filter');
        filterBtns.forEach(function(b) { b.classList.remove('active'); });
        btn.classList.add('active');

        if (category === 'all') {
          filteredReels = REELS_DATA.slice();
        } else {
          filteredReels = REELS_DATA.filter(function(r) { return r.category === category; });
        }
        activeReelIndex = 0;
        renderReelsCarousel();
      });
    });

    // Touch gestures & Scroll listener for carousel centering & active index synchronization
    var reelsTrackWrapper = document.getElementById('reelsTrackWrapper');
    if (reelsTrackWrapper) {
      var scrollDebounceTimer = null;
      var lastWrapperWidth = reelsTrackWrapper.clientWidth;

      reelsTrackWrapper.addEventListener('scroll', function() {
        if (isCarouselProgrammaticScroll) return;

        clearTimeout(scrollDebounceTimer);
        scrollDebounceTimer = setTimeout(function() {
          if (isCarouselProgrammaticScroll) return;

          var cards = reelsTrackWrapper.querySelectorAll('.reel-card');
          var wrapperCenter = reelsTrackWrapper.scrollLeft + (reelsTrackWrapper.clientWidth / 2);
          var closestIdx = activeReelIndex;
          var minDistance = Infinity;

          cards.forEach(function(card) {
            var idx = parseInt(card.getAttribute('data-index'), 10);
            var cardCenter = card.offsetLeft + (card.offsetWidth / 2);
            var dist = Math.abs(wrapperCenter - cardCenter);
            if (dist < minDistance) {
              minDistance = dist;
              closestIdx = idx;
            }
          });

          if (closestIdx !== activeReelIndex && !isNaN(closestIdx)) {
            cleanupActivePlayer();
            activeReelIndex = closestIdx;
            cards.forEach(function(card, idx) {
              card.classList.toggle('active', idx === activeReelIndex);
            });
            var counterEl = document.getElementById('reelsCounter');
            if (counterEl) {
              var numStr = (activeReelIndex + 1 < 10 ? '0' : '') + (activeReelIndex + 1);
              var totalStr = (filteredReels.length < 10 ? '0' : '') + filteredReels.length;
              counterEl.innerHTML = numStr + " <span>/ " + totalStr + "</span>";
            }
          }
        }, 60);
      }, { passive: true });

      // Only re-center horizontally if width actually changed (prevents vertical mobile address-bar resize jumps)
      window.addEventListener('resize', function() {
        var newWidth = reelsTrackWrapper.clientWidth;
        if (Math.abs(newWidth - lastWrapperWidth) > 10) {
          lastWrapperWidth = newWidth;
          selectReel(activeReelIndex, { smooth: false });
        }
      }, { passive: true });
    }

    // Initialize IntersectionObserver and visibility listeners for Smart Auto-Pause & Resume
    initReelsVisibilityObserver();
  }

  // Smart Reel Visibility Management (IntersectionObserver & Page Visibility)
  function initReelsVisibilityObserver() {
    var reelsSection = document.getElementById('reels');
    var reelsContainer = document.getElementById('reelsContainer') || document.getElementById('reelsTrackWrapper');
    if (!reelsContainer && !reelsSection) return;

    if (reelsIntersectionObserver) {
      try { reelsIntersectionObserver.disconnect(); } catch (e) {}
      reelsIntersectionObserver = null;
    }

    // Helper to pause active playing reel automatically due to visibility change
    function handleAutoPause() {
      if (!activePlayingReelId) return;
      var state = getReelPlaybackState(activePlayingReelId);

      // Check if player is currently playing or buffering
      var isCurrentlyPlaying = state.isPlaying;
      if (activeYtPlayer && typeof activeYtPlayer.getPlayerState === 'function') {
        try {
          var pState = activeYtPlayer.getPlayerState();
          if (window.YT && window.YT.PlayerState) {
            if (pState === window.YT.PlayerState.PLAYING || pState === window.YT.PlayerState.BUFFERING) {
              isCurrentlyPlaying = true;
            } else if (pState === window.YT.PlayerState.PAUSED) {
              isCurrentlyPlaying = false;
            }
          }
        } catch (e) {}
      }

      if (isCurrentlyPlaying && !state.isManuallyPaused) {
        state.wasPlayingBeforeHidden = true;
        state.isAutoPaused = true;
        state.isPlaying = false;
        isAutoPausingOrResuming = true;
        try {
          if (activeYtPlayer && typeof activeYtPlayer.pauseVideo === 'function') {
            activeYtPlayer.pauseVideo();
          }
        } catch (e) {}
        setTimeout(function() {
          isAutoPausingOrResuming = false;
        }, 50);
      }
    }

    // Helper to resume active playing reel automatically when visible again
    function handleAutoResume() {
      if (!activePlayingReelId) return;
      var state = getReelPlaybackState(activePlayingReelId);

      // Resume only if it was playing before becoming hidden and was not manually paused
      if (state.wasPlayingBeforeHidden && state.isAutoPaused && !state.isManuallyPaused) {
        state.wasPlayingBeforeHidden = false;
        state.isAutoPaused = false;
        state.isPlaying = true;
        isAutoPausingOrResuming = true;

        if (state.index >= 0 && state.index === activeReelIndex) {
          playReel(state.index, { isResume: true });
        }

        setTimeout(function() {
          isAutoPausingOrResuming = false;
        }, 50);
      }
    }

    // Setup IntersectionObserver if supported
    if ('IntersectionObserver' in window) {
      // Sensible threshold with hysteresis: pause below 0.35, resume above 0.5
      var targetElement = reelsContainer || reelsSection;
      try {
        reelsIntersectionObserver = new IntersectionObserver(function(entries) {
          entries.forEach(function(entry) {
            if (entry.isIntersecting && entry.intersectionRatio >= 0.5) {
              handleAutoResume();
            } else if (!entry.isIntersecting || entry.intersectionRatio < 0.35) {
              handleAutoPause();
            }
          });
        }, {
          root: null,
          threshold: [0, 0.25, 0.35, 0.5, 0.75, 1.0]
        });

        reelsIntersectionObserver.observe(targetElement);
      } catch (err) {}
    }

    // Document Visibility Change (Tab Blur / Minimization)
    document.addEventListener('visibilitychange', function() {
      if (document.hidden) {
        handleAutoPause();
      } else {
        // Tab restored: check if reel container is currently visible in viewport
        var isVisible = true;
        var el = reelsContainer || reelsSection;
        if (el && typeof el.getBoundingClientRect === 'function') {
          var rect = el.getBoundingClientRect();
          var windowHeight = window.innerHeight || document.documentElement.clientHeight;
          // Sufficiently visible if at least 35% of element is in view or crosses viewport center
          var visibleHeight = Math.max(0, Math.min(rect.bottom, windowHeight) - Math.max(rect.top, 0));
          var ratio = rect.height > 0 ? (visibleHeight / rect.height) : 0;
          isVisible = ratio >= 0.35;
        }

        if (isVisible) {
          handleAutoResume();
        }
      }
    });

    // Window Blur/Focus fallback for older browsers or app webviews
    window.addEventListener('blur', function() {
      handleAutoPause();
    });
    window.addEventListener('focus', function() {
      var isVisible = true;
      var el = reelsContainer || reelsSection;
      if (el && typeof el.getBoundingClientRect === 'function') {
        var rect = el.getBoundingClientRect();
        var windowHeight = window.innerHeight || document.documentElement.clientHeight;
        var visibleHeight = Math.max(0, Math.min(rect.bottom, windowHeight) - Math.max(rect.top, 0));
        var ratio = rect.height > 0 ? (visibleHeight / rect.height) : 0;
        isVisible = ratio >= 0.35;
      }
      if (isVisible) {
        handleAutoResume();
      }
    });
  }

  // Render Graphic Design Gallery & Lightbox Modal
  var currentGfxIndex = 0;
  var filteredGraphics = GRAPHICS_DATA.slice();
  var savedLightboxScrollY = 0;
  var lastTriggeringGfxElement = null;

  function renderGraphicsGrid() {
    var grid = document.getElementById('graphicsGrid');
    if (!grid) return;

    // Check loading state
    if (bloggerFeedState.isLoading && !bloggerFeedState.hasLoadedOnce && !filteredGraphics.length) {
      grid.innerHTML = "<div style='grid-column: 1 / -1; padding: 60px 24px; text-align: center; background: var(--card); border: 1px dashed var(--border); border-radius: 20px; color: var(--muted);'>" +
        "<div class='reel-spinner' style='display: block; margin: 0 auto 16px;'></div>" +
        "<div style='font-size: 0.95rem; font-weight: 500;'>Loading published graphics...</div>" +
        "</div>";
      return;
    }

    // Check error state
    if (bloggerFeedState.graphicsError && !filteredGraphics.length) {
      grid.innerHTML = "<div style='grid-column: 1 / -1; padding: 50px 24px; text-align: center; background: var(--card); border: 1px dashed var(--border); border-radius: 20px; color: var(--muted);'>" +
        "<svg xmlns='http://www.w3.org/2000/svg' width='40' height='40' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round' stroke-linejoin='round' style='margin: 0 auto 16px; opacity: 0.6;'><circle cx='12' cy='12' r='10'/><line x1='12' y1='8' x2='12' y2='12'/><line x1='12' y1='16' x2='12.01' y2='16'/></svg>" +
        "<h3 style='font-family: var(--font-heading); font-size: 1.1rem; color: var(--text); margin-bottom: 8px;'>Unable to Load Graphics</h3>" +
        "<p style='font-size: 0.88rem; max-width: 460px; margin: 0 auto 20px;'>" + escapeHtml(bloggerFeedState.graphicsErrorMsg || 'Could not fetch graphic designs from Blogger feed.') + "</p>" +
        "<button id='graphicsRetryBtn' type='button' class='btn btn-primary' style='padding: 8px 20px; font-size: 0.85rem;'>Retry</button>" +
        "</div>";
      var retryGfxBtn = document.getElementById('graphicsRetryBtn');
      if (retryGfxBtn) {
        retryGfxBtn.addEventListener('click', function() {
          discoverBloggerPosts();
        });
      }
      return;
    }

    if (!filteredGraphics.length) {
      grid.innerHTML = "<div style='grid-column: 1 / -1; padding: 48px 24px; text-align: center; background: var(--card); border: 1px dashed var(--border); border-radius: 20px; color: var(--muted);'>" +
        "<svg xmlns='http://www.w3.org/2000/svg' width='48' height='48' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round' style='margin: 0 auto 16px; display: block; opacity: 0.5;'><rect width='18' height='18' x='3' y='3' rx='2' ry='2'/><circle cx='9' cy='9' r='2'/><path d='m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21'/></svg>" +
        "<h3 style='font-family: var(--font-heading); font-size: 1.1rem; color: var(--text); margin-bottom: 8px;'>No Graphic Projects Found</h3>" +
        "<p style='font-size: 0.88rem; max-width: 460px; margin: 0 auto;'>Publish posts with label <strong>'Graphics'</strong> on your Blogger site to automatically populate this showcase with your artwork.</p>" +
        "</div>";
      return;
    }

    var html = '';
    filteredGraphics.forEach(function(gfx, idx) {
      if (!gfx.image) return;
      html += "<article class='graphic-card' data-gfx-index='" + idx + "'>";
      html += "<div class='graphic-image-wrap'>";
      html += "<span class='graphic-badge'>" + (gfx.badge || 'CREATIVE') + "</span>";
      html += "<img src='" + escapeHtml(gfx.image) + "' alt='" + escapeHtml(gfx.title) + "' loading='lazy' onerror='this.style.display=&quot;none&quot;;'/>";
      html += "</div>";
      html += "<div class='graphic-info'>";
      html += "<h3>" + escapeHtml(gfx.title) + "</h3>";
      html += "<p>" + (gfx.categoryLabel || gfx.category) + "</p>";
      html += "</div></article>";
    });

    grid.innerHTML = html;

    var cards = grid.querySelectorAll('.graphic-card');
    cards.forEach(function(card) {
      card.addEventListener('click', function() {
        var idx = parseInt(card.getAttribute('data-gfx-index'), 10);
        openLightbox(idx);
      });
    });
  }

  function openLightbox(index, triggerEl) {
    if (index < 0 || index >= filteredGraphics.length) return;
    currentGfxIndex = index;
    var gfx = filteredGraphics[currentGfxIndex];

    var modal = document.getElementById('lightboxModal');
    var body = document.getElementById('lightboxBody');
    var titleEl = document.getElementById('lightboxTitle');
    var catEl = document.getElementById('lightboxCat');

    if (!modal || !body) return;

    if (triggerEl) {
      lastTriggeringGfxElement = triggerEl;
    } else {
      lastTriggeringGfxElement = document.querySelector('.graphic-card[data-gfx-index="' + index + '"]');
    }

    if (gfx.image) {
      body.innerHTML = "<img src='" + gfx.image + "' alt='" + gfx.title + "'/>";
    } else {
      body.innerHTML = "<div style='padding: 40px; text-align: center; color: #FFFFFF;'>Artwork preview unavailable</div>";
    }

    if (titleEl) titleEl.textContent = gfx.title;
    if (catEl) catEl.textContent = gfx.categoryLabel || gfx.category;

    if (!modal.classList.contains('open')) {
      savedLightboxScrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
      modal.classList.add('open');
      modal.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    }
  }

  function closeLightbox() {
    var modal = document.getElementById('lightboxModal');
    if (!modal || !modal.classList.contains('open')) return;

    modal.classList.remove('open');
    modal.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';

    // Restore exact document scroll position without jumping
    if (typeof window.scrollTo === 'function') {
      window.scrollTo(0, savedLightboxScrollY);
    }

    // Restore focus to the card that opened the lightbox
    if (lastTriggeringGfxElement && typeof lastTriggeringGfxElement.focus === 'function') {
      try { lastTriggeringGfxElement.focus(); } catch (e) {}
    }
  }

  function setupGraphicsControls() {
    var filterBtns = document.querySelectorAll('#graphicsFilterGroup .filter');
    var closeBtn = document.getElementById('lightboxClose');
    var prevBtn = document.getElementById('lightboxPrev');
    var nextBtn = document.getElementById('lightboxNext');
    var modal = document.getElementById('lightboxModal');

    filterBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        var category = btn.getAttribute('data-gfx-filter');
        filterBtns.forEach(function(b) { b.classList.remove('active'); });
        btn.classList.add('active');

        if (category === 'all') {
          filteredGraphics = GRAPHICS_DATA.slice();
        } else {
          filteredGraphics = GRAPHICS_DATA.filter(function(g) { return g.category === category; });
        }
        renderGraphicsGrid();
      });
    });

    if (closeBtn) closeBtn.addEventListener('click', closeLightbox);

    if (prevBtn) {
      prevBtn.addEventListener('click', function() {
        if (!filteredGraphics.length) return;
        var prevIdx = (currentGfxIndex - 1 + filteredGraphics.length) % filteredGraphics.length;
        openLightbox(prevIdx);
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function() {
        if (!filteredGraphics.length) return;
        var nextIdx = (currentGfxIndex + 1) % filteredGraphics.length;
        openLightbox(nextIdx);
      });
    }

    if (modal) {
      modal.addEventListener('click', function(e) {
        if (e.target === modal) closeLightbox();
      });
    }

    // Keyboard controls
    document.addEventListener('keydown', function(e) {
      if (modal && modal.classList.contains('open')) {
        if (e.key === 'Escape') closeLightbox();
        else if (e.key === 'ArrowLeft' && prevBtn) prevBtn.click();
        else if (e.key === 'ArrowRight' && nextBtn) nextBtn.click();
      } else if (document.activeElement && document.activeElement.closest('#reelsContainer')) {
        if (e.key === 'ArrowLeft') {
          var rPrev = document.getElementById('reelPrevBtn');
          if (rPrev) rPrev.click();
        } else if (e.key === 'ArrowRight') {
          var rNext = document.getElementById('reelNextBtn');
          if (rNext) rNext.click();
        }
      }
    });
  }

  // Comprehensive Blogger Feed Discovery with Pagination and CORS Resiliency
  var isDiscoveringBloggerPosts = false;
  var seenBloggerPostIds = {};

  function fetchBloggerFeedBatch(startIndex, maxResults) {
    return new Promise(function(resolve, reject) {
      // Build feed URL based on current origin or configured postsUrl
      var baseUrl = STUDIO_CONFIG.bloggerFeed.postsUrl || '/feeds/posts/default?alt=json';
      // Strip any existing alt, start-index, or max-results params
      var urlWithoutQuery = baseUrl.split('?')[0];
      // Check if protocol/host is needed (e.g. running on local file or preview)
      if (urlWithoutQuery.indexOf('http') !== 0 && typeof window !== 'undefined' && window.location) {
        if (window.location.protocol === 'http:' || window.location.protocol === 'https:') {
          urlWithoutQuery = window.location.origin + urlWithoutQuery;
        } else {
          // If viewing from file:// or custom, fallback to default SynFusion blogger domain
          urlWithoutQuery = 'https://synfusion.blogspot.com' + urlWithoutQuery;
        }
      }

      var jsonUrl = urlWithoutQuery + '?alt=json&start-index=' + startIndex + '&max-results=' + maxResults;

      // Attempt 1: Standard fetch
      if (typeof fetch === 'function') {
        var fetchController = typeof AbortController !== 'undefined' ? new AbortController() : null;
        var fetchTimeout = setTimeout(function() {
          if (fetchController) fetchController.abort();
        }, 10000);

        fetch(jsonUrl, {
          method: 'GET',
          headers: { 'Accept': 'application/json' },
          signal: fetchController ? fetchController.signal : undefined
        })
        .then(function(res) {
          clearTimeout(fetchTimeout);
          if (!res.ok) throw new Error('HTTP ' + res.status);
          return res.json();
        })
        .then(function(data) {
          resolve(data);
        })
        .catch(function(err) {
          clearTimeout(fetchTimeout);
          // Attempt 2: JSONP fallback for cross-origin or CORS restriction
          fetchBloggerFeedJsonp(urlWithoutQuery, startIndex, maxResults)
            .then(resolve)
            .catch(function(jsonpErr) {
              reject(new Error(err.message || 'Feed request failed'));
            });
        });
      } else {
        // Fallback to JSONP directly if fetch is not supported
        fetchBloggerFeedJsonp(urlWithoutQuery, startIndex, maxResults)
          .then(resolve)
          .catch(reject);
      }
    });
  }

  // JSONP fallback for Blogger public feeds (bypasses CORS restrictions)
  function fetchBloggerFeedJsonp(baseUrl, startIndex, maxResults) {
    return new Promise(function(resolve, reject) {
      var callbackName = '__blogger_feed_cb_' + Date.now() + '_' + Math.floor(Math.random() * 10000);
      var script = document.createElement('script');
      var timeout = setTimeout(function() {
        cleanup();
        reject(new Error('JSONP feed request timed out'));
      }, 12000);

      function cleanup() {
        clearTimeout(timeout);
        delete window[callbackName];
        if (script && script.parentNode) {
          script.parentNode.removeChild(script);
        }
      }

      window[callbackName] = function(data) {
        cleanup();
        resolve(data);
      };

      script.onerror = function() {
        cleanup();
        reject(new Error('JSONP script loading error'));
      };

      var separator = baseUrl.indexOf('?') === -1 ? '?' : '&';
      script.src = baseUrl + separator + 'alt=json-in-script&callback=' + callbackName + '&start-index=' + startIndex + '&max-results=' + maxResults;
      document.head.appendChild(script);
    });
  }

  function discoverBloggerPosts() {
    if (isDiscoveringBloggerPosts) return;
    isDiscoveringBloggerPosts = true;

    bloggerFeedState.isLoading = true;
    bloggerFeedState.reelsError = false;
    bloggerFeedState.graphicsError = false;
    bloggerFeedState.reelsErrorMsg = '';
    bloggerFeedState.graphicsErrorMsg = '';

    renderReelsCarousel();
    renderGraphicsGrid();

    var maxPerPage = STUDIO_CONFIG.bloggerFeed.maxResultsPerPage || 50;
    var maxTotal = STUDIO_CONFIG.bloggerFeed.maxTotalPosts || 150;
    var currentStartIndex = 1;

    var discoveredReels = [];
    var discoveredGraphics = [];

    var targetReelsLabel = (STUDIO_CONFIG.bloggerFeed.reelsLabel || 'reels').toLowerCase().trim();
    var targetGraphicsLabel = (STUDIO_CONFIG.bloggerFeed.graphicsLabel || 'graphics').toLowerCase().trim();

    function fetchNextBatch() {
      fetchBloggerFeedBatch(currentStartIndex, maxPerPage)
        .then(function(data) {
          if (!data || !data.feed) {
            finishDiscovery(null, 'Malformed Blogger feed structure');
            return;
          }

          var totalResults = 0;
          if (data.feed.openSearch$totalResults && data.feed.openSearch$totalResults.$t) {
            totalResults = parseInt(data.feed.openSearch$totalResults.$t, 10) || 0;
          }

          var entries = data.feed.entry || [];
          if (typeof console !== 'undefined' && console.log) {
            console.log('[Blogger Feed] Received ' + entries.length + ' entries (Batch starting ' + currentStartIndex + ')');
          }

          entries.forEach(function(entry) {
            try {
              var postId = (entry.id && entry.id.$t) ? entry.id.$t : (entry.title ? entry.title.$t : Math.random().toString());
              if (seenBloggerPostIds[postId]) return;
              seenBloggerPostIds[postId] = true;

              // Extract post title strictly from entry.title.$t
              var rawTitle = (entry.title && typeof entry.title.$t === 'string') ? entry.title.$t : '';
              var title = decodeHtmlEntities(rawTitle).trim();

              // Extract canonical / alternate post URL
              var postUrl = '';
              if (entry.link && Array.isArray(entry.link)) {
                var altLink = entry.link.find(function(l) { return l.rel === 'alternate'; });
                if (altLink && altLink.href) postUrl = altLink.href;
              }
              var content = (entry.content && entry.content.$t) ? entry.content.$t : ((entry.summary && entry.summary.$t) ? entry.summary.$t : '');
              var ytId = extractYouTubeIdFromText(content);
              if (!ytId && postUrl) ytId = extractYouTubeIdFromText(postUrl);

              // Use the actual Blogger post title; use a generic fallback only when it is truly missing.
              if (!title || !title.trim()) title = ytId ? 'Creative Reel' : 'Creative Artwork';

              var publishedDate = (entry.published && entry.published.$t) ? new Date(entry.published.$t).getTime() : 0;

              // Extract labels case-insensitively
              var categoriesRaw = entry.category ? entry.category.map(function(c) { return c.term; }) : [];
              var categoriesLower = categoriesRaw.map(function(c) { return (c || '').toLowerCase().trim(); });

              var hasExplicitReelsLabel = categoriesLower.indexOf(targetReelsLabel) !== -1 ||
                categoriesLower.some(function(c) {
                  return ['reel', '2d animation', '3d animation', 'video editing', 'ai product ads', 'motion graphics', 'short-form'].indexOf(c) !== -1;
                });

              var hasExplicitGraphicsLabel = categoriesLower.indexOf(targetGraphicsLabel) !== -1 ||
                categoriesLower.some(function(c) {
                  return ['graphic', 'logo design', 'social media posts', 'youtube thumbnails', 'posters & banners', 'advertising creatives', 'brand identity', 'branding', 'thumbnails', 'posters', 'social media creatives'].indexOf(c) !== -1;
                });

              // REELS CLASSIFICATION RULES:
              // 1. If explicit Reels label and has valid YT ID, it's a Reel.
              // 2. If valid YouTube video detected, and NO explicit Graphics label, treat as Reel.
              // 3. If post has both Graphics label and YouTube video, prioritize based on artwork presence:
              //    if it contains graphic artwork, it goes to Graphics, but can also be in Reels if explicitly labeled Reels.
              var isReelCandidate = (hasExplicitReelsLabel && ytId) || (ytId && !hasExplicitGraphicsLabel);

              if (isReelCandidate && ytId) {
                // Determine reel category and badge label case-insensitively
                // Motion Graphics -> MOTION
                // 3D Animation -> 3D
                // 2D Animation -> 2D
                // Video Editing -> EDITING
                // AI Product Ads -> AI ADS
                var reelCat = 'motion';
                var reelBadge = 'MOTION';

                if (categoriesLower.indexOf('3d animation') !== -1 || categoriesLower.indexOf('3d') !== -1) {
                  reelCat = '3d';
                  reelBadge = '3D';
                } else if (categoriesLower.indexOf('2d animation') !== -1 || categoriesLower.indexOf('2d') !== -1) {
                  reelCat = '2d';
                  reelBadge = '2D';
                } else if (categoriesLower.indexOf('video editing') !== -1 || categoriesLower.indexOf('editing') !== -1) {
                  reelCat = 'editing';
                  reelBadge = 'EDITING';
                } else if (categoriesLower.indexOf('ai product ads') !== -1 || categoriesLower.indexOf('ai-ads') !== -1 || categoriesLower.indexOf('ai product ad') !== -1) {
                  reelCat = 'ai-ads';
                  reelBadge = 'AI ADS';
                } else if (categoriesLower.indexOf('motion graphics') !== -1 || categoriesLower.indexOf('motion') !== -1) {
                  reelCat = 'motion';
                  reelBadge = 'MOTION';
                }

                // Extract custom thumbnail if present
                // Priority: 1. Content image explicitly designated or present in post
                //           2. entry.media$thumbnail if not a generic low-res YT grab
                //           3. Automatic YouTube maxresdefault thumbnail
                var contentImages = extractImagesFromContent(content);
                var customCover = '';
                if (contentImages.length > 0) {
                  var firstImg = contentImages[0];
                  if (!/ytimg\.com|img\.youtube\.com/i.test(firstImg)) {
                    customCover = firstImg;
                  }
                }
                if (!customCover && entry.media$thumbnail && entry.media$thumbnail.url) {
                  var mediaThumb = upgradeBloggerImageUrl(entry.media$thumbnail.url);
                  if (!/ytimg\.com|img\.youtube\.com/i.test(mediaThumb)) {
                    customCover = mediaThumb;
                  }
                }

                var thumb = customCover || ('https://i.ytimg.com/vi/' + ytId + '/maxresdefault.jpg');

                discoveredReels.push({
                  id: 'blogger-reel-' + ytId,
                  title: title,
                  category: reelCat,
                  categoryLabel: reelBadge,
                  badge: reelBadge,
                  youtubeId: ytId,
                  thumbnail: thumb,
                  description: title,
                  featured: true,
                  publishedDate: publishedDate,
                  postUrl: postUrl
                });
              }

              // GRAPHICS CLASSIFICATION RULES:
              // A published post with artwork images and NO YouTube video automatically belongs in Graphics,
              // even when the author has not added the Graphics label. Explicit Graphics-labeled posts are
              // also eligible, but YouTube preview thumbnails alone must never count as artwork.
              var contentImages = extractImagesFromContent(content).filter(function(url) {
                return url && !/ytimg\.com|img\.youtube\.com|youtube\.com\/vi\//i.test(url);
              });
              var mediaImage = (entry.media$thumbnail && entry.media$thumbnail.url)
                ? upgradeBloggerImageUrl(entry.media$thumbnail.url) : '';
              if (mediaImage && /ytimg\.com|img\.youtube\.com|youtube\.com\/vi\//i.test(mediaImage)) mediaImage = '';
              var primaryImage = contentImages.length ? contentImages[0] : mediaImage;
              var shouldShowAsGraphic = !!primaryImage && (!ytId || hasExplicitGraphicsLabel);
              if (shouldShowAsGraphic) {
                // Render real artwork only; never fabricate a demo or gradient placeholder.
                if (primaryImage) {
                  var gfxCat = 'brand';
                  var badge = 'CREATIVE';

                  if (categoriesLower.indexOf('logo design') !== -1 || categoriesLower.indexOf('logo') !== -1) {
                    gfxCat = 'logo'; badge = 'LOGO';
                  } else if (categoriesLower.indexOf('social media posts') !== -1 || categoriesLower.indexOf('social') !== -1) {
                    gfxCat = 'social'; badge = 'SOCIAL';
                  } else if (categoriesLower.indexOf('youtube thumbnails') !== -1 || categoriesLower.indexOf('thumbnail') !== -1) {
                    gfxCat = 'thumbnail'; badge = 'THUMBNAIL';
                  } else if (categoriesLower.indexOf('posters & banners') !== -1 || categoriesLower.indexOf('poster') !== -1) {
                    gfxCat = 'poster'; badge = 'POSTER';
                  } else if (categoriesLower.indexOf('advertising creatives') !== -1 || categoriesLower.indexOf('ads') !== -1) {
                    gfxCat = 'ads'; badge = 'AD CREATIVE';
                  } else if (categoriesLower.indexOf('brand identity') !== -1 || categoriesLower.indexOf('branding') !== -1) {
                    gfxCat = 'brand'; badge = 'BRANDING';
                  }

                  discoveredGraphics.push({
                    id: 'blogger-gfx-' + postId.replace(/[^a-zA-Z0-9_-]/g, '_'),
                    title: title,
                    category: gfxCat,
                    categoryLabel: badge,
                    badge: badge,
                    image: primaryImage,
                    publishedDate: publishedDate,
                    postUrl: postUrl
                  });
                }
              }
            } catch (entryErr) {
              if (typeof console !== 'undefined' && console.warn) {
                console.warn('[Blogger Feed] Skipping malformed post entry:', entryErr);
              }
            }
          });

          // Check if more entries exist and within maxTotal limit
          currentStartIndex += entries.length;
          if (entries.length >= maxPerPage && currentStartIndex <= totalResults && currentStartIndex < maxTotal) {
            fetchNextBatch();
          } else {
            finishDiscovery(null, '');
          }
        })
        .catch(function(err) {
          finishDiscovery(err, err.message || 'Unable to connect to Blogger feed');
        });
    }

    function finishDiscovery(err, errMsg) {
      isDiscoveringBloggerPosts = false;
      bloggerFeedState.isLoading = false;
      bloggerFeedState.hasLoadedOnce = true;

      if (err) {
        if (typeof console !== 'undefined' && console.error) {
          console.error('[Blogger Feed Discovery Error]:', err);
        }
        // Only set error state if no existing content is present
        if (!REELS_DATA.length) {
          bloggerFeedState.reelsError = true;
          bloggerFeedState.reelsErrorMsg = errMsg;
        }
        if (!GRAPHICS_DATA.length) {
          bloggerFeedState.graphicsError = true;
          bloggerFeedState.graphicsErrorMsg = errMsg;
        }
        renderReelsCarousel();
        renderGraphicsGrid();
        return;
      }

      // Merge and sort discovered Reels
      if (discoveredReels.length > 0) {
        // Remove duplicates by youtubeId
        discoveredReels.forEach(function(r) {
          var existingIdx = REELS_DATA.findIndex(function(ex) { return ex.youtubeId === r.youtubeId; });
          if (existingIdx !== -1) {
            REELS_DATA[existingIdx] = r;
          } else {
            REELS_DATA.unshift(r);
          }
        });

        // Sort by publication date descending where available
        REELS_DATA.sort(function(a, b) {
          return (b.publishedDate || 0) - (a.publishedDate || 0);
        });

        filteredReels = REELS_DATA.slice();
        renderReelsCarousel();
      } else {
        renderReelsCarousel();
      }

      // Merge and sort discovered Graphics
      if (discoveredGraphics.length > 0) {
        discoveredGraphics.forEach(function(g) {
          var existingIdx = GRAPHICS_DATA.findIndex(function(ex) { return ex.image === g.image; });
          if (existingIdx !== -1) {
            GRAPHICS_DATA[existingIdx] = g;
          } else {
            GRAPHICS_DATA.unshift(g);
          }
        });

        GRAPHICS_DATA.sort(function(a, b) {
          return (b.publishedDate || 0) - (a.publishedDate || 0);
        });

        filteredGraphics = GRAPHICS_DATA.slice();
        renderGraphicsGrid();
      } else {
        renderGraphicsGrid();
      }

      if (typeof console !== 'undefined' && console.log) {
        console.log('[Blogger Feed] Discovery finished. Classified Reels: ' + discoveredReels.length + ', Classified Graphics: ' + discoveredGraphics.length);
      }
    }

    fetchNextBatch();
  }

  // WhatsApp Quotation Request Form Handler
  function setupWhatsAppQuoteForm() {
    var form = document.getElementById('whatsappQuoteForm');
    if (!form) return;

    var nameInput = document.getElementById('quoteName');
    var serviceSelect = document.getElementById('quoteService');
    var reqsTextarea = document.getElementById('quoteRequirements');
    var submitBtn = document.getElementById('quoteSubmitBtn');
    var feedbackEl = document.getElementById('quoteStatusFeedback');

    var nameError = document.getElementById('quoteNameError');
    var serviceError = document.getElementById('quoteServiceError');
    var reqsError = document.getElementById('quoteRequirementsError');

    var isSubmitting = false;

    // Helper to clear errors
    function clearErrors() {
      if (nameError) nameError.classList.remove('visible');
      if (serviceError) serviceError.classList.remove('visible');
      if (reqsError) reqsError.classList.remove('visible');
      if (nameInput) nameInput.classList.remove('field-error');
      if (serviceSelect) serviceSelect.classList.remove('field-error');
      if (reqsTextarea) reqsTextarea.classList.remove('field-error');
      if (feedbackEl) {
        feedbackEl.className = 'quote-status-feedback';
        feedbackEl.textContent = '';
      }
    }

    // Real-time input listeners to clear field-level error when user starts typing/selecting
    if (nameInput) {
      nameInput.addEventListener('input', function() {
        if (nameInput.value.trim().length > 0) {
          nameInput.classList.remove('field-error');
          if (nameError) nameError.classList.remove('visible');
        }
      });
    }
    if (serviceSelect) {
      serviceSelect.addEventListener('change', function() {
        if (serviceSelect.value) {
          serviceSelect.classList.remove('field-error');
          if (serviceError) serviceError.classList.remove('visible');
        }
      });
    }
    if (reqsTextarea) {
      reqsTextarea.addEventListener('input', function() {
        if (reqsTextarea.value.trim().length > 0) {
          reqsTextarea.classList.remove('field-error');
          if (reqsError) reqsError.classList.remove('visible');
        }
      });
    }

    form.addEventListener('submit', function(e) {
      e.preventDefault();

      if (isSubmitting) return;

      clearErrors();

      var nameVal = (nameInput && nameInput.value) ? nameInput.value.trim() : '';
      var serviceVal = (serviceSelect && serviceSelect.value) ? serviceSelect.value.trim() : '';
      var reqsVal = (reqsTextarea && reqsTextarea.value) ? reqsTextarea.value.trim() : '';

      var firstInvalid = null;

      // Validate Name
      if (!nameVal) {
        if (nameInput) nameInput.classList.add('field-error');
        if (nameError) nameError.classList.add('visible');
        if (!firstInvalid) firstInvalid = nameInput;
      }

      // Validate Field / Service
      if (!serviceVal) {
        if (serviceSelect) serviceSelect.classList.add('field-error');
        if (serviceError) serviceError.classList.add('visible');
        if (!firstInvalid) firstInvalid = serviceSelect;
      }

      // Validate Detailed Requirements
      if (!reqsVal) {
        if (reqsTextarea) reqsTextarea.classList.add('field-error');
        if (reqsError) reqsError.classList.add('visible');
        if (!firstInvalid) firstInvalid = reqsTextarea;
      }

      // Focus first invalid element
      if (firstInvalid) {
        try {
          firstInvalid.focus();
        } catch (err) {}
        return;
      }

      // Prevent accidental rapid duplicate submissions
      isSubmitting = true;
      if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.style.opacity = '0.75';
      }

      // Construct formatted WhatsApp message strictly matching specification
      var brandName = (STUDIO_CONFIG && STUDIO_CONFIG.brandName) ? STUDIO_CONFIG.brandName : 'Singh Creative Studio';
      var tagline = (STUDIO_CONFIG && STUDIO_CONFIG.tagline) ? STUDIO_CONFIG.tagline : 'Ideas Made Visible.';
      var waPhone = '919334603912';

      var message = '✨ NEW QUOTATION REQUEST\n' +
        '━━━━━━━━━━━━━━━━━━\n\n' +
        '👤 Client Name:\n' + nameVal + '\n\n' +
        '🎯 Service / Field:\n' + serviceVal + '\n\n' +
        '📝 Project Requirements:\n' + reqsVal + '\n\n' +
        '━━━━━━━━━━━━━━━━━━\n' +
        '📩 Source: ' + brandName + '\n' +
        '💡 Tagline: ' + tagline + '\n\n' +
        'Please review this request and share the next steps and quotation. Thank you!';

      var waUrl = 'https://wa.me/' + waPhone + '?text=' + encodeURIComponent(message);

      // Open WhatsApp safely in mobile and desktop
      try {
        var openedWin = window.open(waUrl, '_blank', 'noopener,noreferrer');
        if (!openedWin || openedWin.closed || typeof openedWin.closed === 'undefined') {
          // If popup is blocked, redirect window location safely
          window.location.href = waUrl;
        }

        if (feedbackEl) {
          feedbackEl.className = 'quote-status-feedback info';
          feedbackEl.textContent = 'Your quotation request is ready in WhatsApp. Review it and tap Send.';
        }
      } catch (openErr) {
        if (feedbackEl) {
          feedbackEl.className = 'quote-status-feedback error';
          feedbackEl.textContent = 'Could not open WhatsApp automatically. Please click the button again or contact us directly on WhatsApp at +' + waPhone + '.';
        }
      }

      // Re-enable button after a brief cooldown to allow retry if desired
      setTimeout(function() {
        isSubmitting = false;
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.style.opacity = '1';
        }
      }, 2500);
    });
  }

  // Initialize Reels, Graphics, and Contact Quotation Modules
  renderReelsCarousel();
  setupReelsControls();
  renderGraphicsGrid();
  setupGraphicsControls();
  setupWhatsAppQuoteForm();
  discoverBloggerPosts();

})();
//
